import { usePendingWrites, useSyncStatus } from '../hooks/use-store';
import { useOnline } from '../offline/use-online';

/**
 * What the app is doing with your writing, in three words or fewer.
 *
 * Worth having in the chrome rather than in a toast: "is my writing safe" is a question people
 * ask constantly and silently, and an app that only speaks up when something breaks does not
 * answer it.
 *
 * Three signals feed one badge, in order of how alarming they are: whether the browser thinks it
 * is online, what the sync engine (note bodies) has to say, and how many metadata writes are
 * still queued. A pending count is shown even while "offline", because "offline, 3 waiting" is a
 * materially different situation from "offline, nothing waiting".
 */

interface Label {
  readonly text: string;
  readonly hint: string;
}

const LABELS: Record<string, Label> = {
  idle: { text: 'Synced', hint: 'Everything you have written is on the server.' },
  syncing: { text: 'Syncing…', hint: 'Sending your latest changes.' },
  offline: {
    text: 'Offline',
    hint: 'Your changes are saved on this device and will send when the server is reachable.',
  },
  error: {
    text: 'Needs attention',
    hint: 'The server refused something, or the session ended. Try signing in again.',
  },
};

export interface SyncBadgeProps {
  /** Ask the workspace to try again now. */
  readonly onFlush?: () => void;
}

export function SyncBadge({ onFlush }: SyncBadgeProps): React.JSX.Element {
  const status = useSyncStatus();
  const pending = usePendingWrites();
  const online = useOnline();

  const effective = !online ? 'offline' : pending > 0 && status === 'idle' ? 'syncing' : status;
  const label = LABELS[effective] ?? LABELS['idle'] ?? { text: 'Synced', hint: '' };
  const suffix = pending > 0 ? ` · ${pending} waiting` : '';

  const content = (
    <>
      <span aria-hidden="true" className="sync-badge__dot" />
      {label.text}
      {suffix}
    </>
  );

  if (onFlush === undefined) {
    return (
      <span className="sync-badge" data-status={effective} title={label.hint}>
        {content}
      </span>
    );
  }

  return (
    <button
      className="sync-badge sync-badge--action"
      data-status={effective}
      onClick={onFlush}
      title={`${label.hint} Click to try now.`}
      type="button"
    >
      {content}
    </button>
  );
}
