import type { CollectionId, Note, NoteId, TagName } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { buildFilter, EMPTY_FILTER_DRAFT, type FilterDraft } from '../filters/filter-draft';
import { useNoteActions } from '../hooks/use-note-actions';
import { type Shortcut, useShortcuts } from '../hooks/use-shortcuts';
import { useLibrary, useNoteList, usePendingWrites } from '../hooks/use-store';
import type { ThemeControl } from '../hooks/use-theme';
import { useReconnect } from '../offline/use-online';
import type { Route } from '../routing/routes';
import { routeTitle, routeToHash } from '../routing/routes';
import { useNavigate } from '../routing/use-route';
import { useWorkspace } from '../session/session-context';
import { CollectionsView, CollectionView } from './collections-view';
import { type Command, CommandPalette } from './command-palette';
import { LibraryView } from './library-view';
import { type ListMode, NoteList } from './note-list';
import { NotePane } from './note-pane';
import { RandomDialog } from './random-dialog';
import { SearchView } from './search-view';
import { SettingsView } from './settings-view';
import { EmptyState } from './states';
import { SyncBadge } from './sync-badge';
import { TagsView, TagView } from './tags-view';
import { TrashView } from './trash-view';

/**
 * The signed-in application.
 *
 * Two panes: the library on the left, whatever is open on the right. The route decides the
 * right-hand pane and nothing else, so the list keeps its scroll position across navigation and
 * an open editor is not torn down because somebody looked at their tags.
 *
 * The filter draft lives here rather than in each view, and that is deliberate: it is what makes
 * "pick one of *these*" mean something. The random draw, the library list and the search box all
 * read the same draft, so narrowing the library narrows the dice.
 */

/** How often to retry a queue the network has not drained on its own. */
const RETRY_INTERVAL_MS = 15_000;

export interface AppShellProps {
  readonly route: Route;
  readonly theme: ThemeControl;
}

export function AppShell({ route, theme }: AppShellProps): React.JSX.Element {
  const workspace = useWorkspace();
  const navigate = useNavigate();
  const actions = useNoteActions();
  const { reload } = useLibrary();
  const { notes, loading, error, stale } = useNoteList();
  const pending = usePendingWrites();

  const [draft, setDraft] = useState<FilterDraft>(EMPTY_FILTER_DRAFT);
  const [listMode, setListMode] = useState<ListMode>('recent');
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [randomOpen, setRandomOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);

  const selectedId = route.name === 'note' ? (route.noteId as NoteId) : null;

  const openNote = useCallback(
    (noteId: NoteId) => {
      setDrawerOpen(false);
      navigate({ name: 'note', noteId });
    },
    [navigate],
  );

  const createNote = useCallback(
    async (title = '') => {
      try {
        const noteId = await actions.create({ title });
        openNote(noteId);
      } catch {
        setNotice('That note could not be created — the server refused it.');
      }
    },
    [actions, openNote],
  );

  /** A `[[wiki-link]]` to a note that does not exist: create it, parented to where it came from. */
  const createLinkedNote = useCallback(
    async (title: string, parentId: NoteId) => {
      try {
        const noteId = await actions.create({ title, parentId });
        openNote(noteId);
      } catch {
        setNotice('That note could not be created — the server refused it.');
      }
    },
    [actions, openNote],
  );

  const flush = useCallback(() => {
    void workspace.flush().then(() => reload());
  }, [reload, workspace]);

  // Reconnecting is the moment everything queued should go. A failed flush simply leaves the
  // queue where it was, so this is safe to fire on a hint.
  useReconnect(flush);

  // …and `online` is not enough on its own: a server that is down while the machine is happily
  // on wi-fi fires no event at all. While anything is waiting, keep asking, unhurriedly.
  useEffect(() => {
    if (pending === 0) {
      return;
    }
    const timer = setInterval(() => void workspace.flush(), RETRY_INTERVAL_MS);
    return () => clearInterval(timer);
  }, [pending, workspace]);

  useEffect(() => {
    document.title = routeTitle(route);
  }, [route]);

  const filter = buildFilter(draft);
  const scopeLabel =
    route.name === 'tag'
      ? `#${route.tag}`
      : route.name === 'collection'
        ? 'this collection'
        : 'your whole library';

  const commands = useMemo<Command[]>(
    () => [
      { id: 'new', label: 'New note', shortcut: 'Ctrl+Alt+N', run: () => void createNote() },
      {
        id: 'random',
        label: 'Pick one for me',
        shortcut: 'Ctrl+Alt+R',
        run: () => setRandomOpen(true),
      },
      {
        id: 'search',
        label: 'Search everything',
        shortcut: 'Ctrl+Shift+F',
        run: () => navigate({ name: 'search', query: '' }),
      },
      { id: 'library', label: 'Go to library', run: () => navigate({ name: 'notes' }) },
      {
        id: 'collections',
        label: 'Go to collections',
        run: () => navigate({ name: 'collections' }),
      },
      { id: 'tags', label: 'Go to tags', run: () => navigate({ name: 'tags' }) },
      { id: 'trash', label: 'Go to trash', run: () => navigate({ name: 'trash' }) },
      { id: 'archive', label: 'Go to archive', run: () => navigate({ name: 'archive' }) },
      { id: 'settings', label: 'Go to settings', run: () => navigate({ name: 'settings' }) },
      { id: 'sync', label: 'Sync now', shortcut: 'Ctrl+S', run: flush },
      {
        id: 'clear-filter',
        label: 'Clear the filter',
        hint: 'Show everything again',
        run: () => setDraft(EMPTY_FILTER_DRAFT),
      },
      {
        id: 'theme',
        label: `Switch to ${theme.theme === 'dark' ? 'light' : 'dark'} theme`,
        run: () => theme.setPreference(theme.theme === 'dark' ? 'light' : 'dark'),
      },
    ],
    [createNote, flush, navigate, theme],
  );

  const shortcuts = useMemo<Shortcut[]>(
    () => [
      {
        key: 'k',
        mod: true,
        whileTyping: true,
        label: 'Command palette',
        run: () => setPaletteOpen((open) => !open),
      },
      {
        key: 'p',
        mod: true,
        whileTyping: true,
        label: 'Quick open',
        run: () => setPaletteOpen(true),
      },
      {
        key: 'f',
        mod: true,
        shift: true,
        whileTyping: true,
        label: 'Search',
        run: () => navigate({ name: 'search', query: '' }),
      },
      {
        key: 'n',
        mod: true,
        alt: true,
        whileTyping: true,
        label: 'New note',
        run: () => void createNote(),
      },
      {
        key: 'r',
        mod: true,
        alt: true,
        whileTyping: true,
        label: 'Pick one for me',
        run: () => setRandomOpen(true),
      },
      { key: 's', mod: true, whileTyping: true, label: 'Save and sync now', run: flush },
      {
        key: 'Escape',
        label: 'Close what is open',
        run: () => {
          setPaletteOpen(false);
          setRandomOpen(false);
          setDrawerOpen(false);
        },
      },
    ],
    [createNote, flush, navigate],
  );

  useShortcuts(shortcuts);

  return (
    <div className="shell" data-drawer={drawerOpen}>
      <header className="shell__header">
        <button
          aria-expanded={drawerOpen}
          aria-label="Show the note list"
          className="shell__drawer-toggle"
          onClick={() => setDrawerOpen(!drawerOpen)}
          type="button"
        >
          ☰
        </button>

        <a
          className="shell__brand"
          href={routeToHash({ name: 'notes' })}
          onClick={(event) => {
            event.preventDefault();
            navigate({ name: 'notes' });
          }}
        >
          Notes
        </a>

        <nav className="shell__nav">
          <NavLink current={route} navigate={navigate} target={{ name: 'notes' }}>
            Library
          </NavLink>
          <NavLink current={route} navigate={navigate} target={{ name: 'search', query: '' }}>
            Search
          </NavLink>
          <NavLink current={route} navigate={navigate} target={{ name: 'collections' }}>
            Collections
          </NavLink>
          <NavLink current={route} navigate={navigate} target={{ name: 'tags' }}>
            Tags
          </NavLink>
          <NavLink current={route} navigate={navigate} target={{ name: 'trash' }}>
            Trash
          </NavLink>
        </nav>

        <div className="shell__status">
          <button
            className="button button--quiet"
            onClick={() => setPaletteOpen(true)}
            title="Go to a note, or run a command"
            type="button"
          >
            <span aria-hidden="true">⌕</span> Go to…
          </button>
          <button
            className="button shell__random"
            onClick={() => setRandomOpen(true)}
            title="Pick a random note from whatever is filtered"
            type="button"
          >
            🎲 Pick one
          </button>
          <SyncBadge onFlush={flush} />
          <button
            className="button button--primary"
            onClick={() => void createNote()}
            type="button"
          >
            New note
          </button>
          <NavLink current={route} navigate={navigate} target={{ name: 'settings' }}>
            Settings
          </NavLink>
        </div>
      </header>

      {notice !== null && (
        <p className="shell__notice" role="status">
          {notice}
          <button className="button button--quiet" onClick={() => setNotice(null)} type="button">
            Dismiss
          </button>
        </p>
      )}

      <div className="shell__body">
        <aside className="shell__sidebar">
          <NoteList
            loading={loading}
            mode={listMode}
            notes={notes}
            onModeChange={setListMode}
            onSelect={openNote}
            selectedId={selectedId}
          />
        </aside>

        {/* The scrim under the mobile drawer. Escape closes it too, via the shortcut table. */}
        {/* biome-ignore lint/a11y/noStaticElementInteractions: Escape is the keyboard path */}
        {/* biome-ignore lint/a11y/useKeyWithClickEvents: Escape is the keyboard path */}
        <div className="shell__scrim" onClick={() => setDrawerOpen(false)} />

        <main className="shell__main">
          <RoutePane
            draft={draft}
            navigate={navigate}
            onCreateLinkedNote={(title, parentId) => void createLinkedNote(title, parentId)}
            onCreateNote={() => void createNote()}
            onDraftChange={setDraft}
            onOpenRandom={() => setRandomOpen(true)}
            openNote={openNote}
            reachable={error === null}
            route={route}
            stale={stale}
            libraryLoading={loading}
            notes={notes}
            theme={theme}
          />
        </main>
      </div>

      <CommandPalette
        commands={commands}
        notes={notes}
        onClose={() => setPaletteOpen(false)}
        onOpenNote={openNote}
        open={paletteOpen}
      />

      <RandomDialog
        draft={draft}
        filter={filter}
        onClose={() => setRandomOpen(false)}
        onOpenNote={openNote}
        open={randomOpen}
        scopeLabel={scopeLabel}
      />
    </div>
  );
}

interface NavLinkProps {
  readonly target: Route;
  readonly current: Route;
  readonly navigate: (route: Route) => void;
  readonly children: React.ReactNode;
}

function NavLink({ target, current, navigate, children }: NavLinkProps): React.JSX.Element {
  return (
    <a
      aria-current={current.name === target.name ? 'page' : undefined}
      className="shell__link"
      href={routeToHash(target)}
      onClick={(event) => {
        if (event.metaKey || event.ctrlKey || event.shiftKey) return;
        event.preventDefault();
        navigate(target);
      }}
    >
      {children}
    </a>
  );
}

interface RoutePaneProps {
  readonly route: Route;
  readonly theme: ThemeControl;
  readonly draft: FilterDraft;
  readonly onDraftChange: (draft: FilterDraft) => void;
  readonly openNote: (noteId: NoteId) => void;
  readonly onCreateNote: () => void;
  readonly onCreateLinkedNote: (title: string, parentId: NoteId) => void;
  readonly onOpenRandom: () => void;
  readonly navigate: (route: Route) => void;
  readonly notes: readonly Note[];
  readonly libraryLoading: boolean;
  readonly stale: boolean;
  readonly reachable: boolean;
}

function RoutePane({
  route,
  theme,
  draft,
  onDraftChange,
  openNote,
  onCreateNote,
  onCreateLinkedNote,
  onOpenRandom,
  navigate,
  notes,
  libraryLoading,
  stale,
  reachable,
}: RoutePaneProps): React.JSX.Element {
  switch (route.name) {
    case 'note':
      return (
        <NotePane
          key={route.noteId}
          noteId={route.noteId as NoteId}
          onCreateLinkedNote={onCreateLinkedNote}
          onOpenNote={openNote}
          theme={theme.theme}
        />
      );
    case 'search':
      return (
        <SearchView
          draft={draft}
          onDraftChange={onDraftChange}
          onOpen={openNote}
          onQueryChange={(query) => navigate({ name: 'search', query })}
          query={route.query}
        />
      );
    case 'collections':
      return (
        <CollectionsView
          onOpenCollection={(collectionId) => navigate({ name: 'collection', collectionId })}
        />
      );
    case 'collection':
      return (
        <CollectionView
          collectionId={route.collectionId as CollectionId}
          draft={draft}
          onBack={() => navigate({ name: 'collections' })}
          onDraftChange={onDraftChange}
          onOpenNote={openNote}
        />
      );
    case 'tags':
      return <TagsView onOpenTag={(tag) => navigate({ name: 'tag', tag })} />;
    case 'tag':
      return (
        <TagView
          draft={draft}
          onDraftChange={onDraftChange}
          onOpenNote={openNote}
          tag={route.tag as TagName}
        />
      );
    case 'trash':
      return <TrashView onOpenNote={openNote} variant="trash" />;
    case 'archive':
      return <TrashView onOpenNote={openNote} variant="archive" />;
    case 'settings':
      return (
        <SettingsView onPreferenceChange={theme.setPreference} preference={theme.preference} />
      );
    case 'notes':
      return (
        <LibraryView
          draft={draft}
          loading={libraryLoading}
          notes={notes}
          onCreateNote={onCreateNote}
          onDraftChange={onDraftChange}
          onOpenNote={openNote}
          onOpenRandom={onOpenRandom}
          reachable={reachable}
          stale={stale}
        />
      );
    default:
      return (
        <EmptyState
          icon="🧭"
          title="There is nothing at that address"
          body={route.name === 'notFound' ? route.path : undefined}
          action={
            <button className="button" onClick={() => navigate({ name: 'notes' })} type="button">
              Back to the library
            </button>
          }
        />
      );
  }
}
