import type { BacklinkSummary, Note, NoteId } from '@rosie-notes/schema';
import { useEffect, useState } from 'react';
import { useWorkspace } from '../session/session-context';
import { displayTitle } from './kinds';

/**
 * What points here, and what this note points at that does not exist yet.
 *
 * Both halves matter and they are different questions. **Backlinks** are how a project note
 * accumulates context without anybody maintaining an index. **Unresolved links** are a to-do
 * list you wrote by accident: `[[Deployment runbook]]` typed in a hurry is a note you have
 * decided to write, and one click here writes it.
 *
 * Backlinks come from the server (`GET /v1/notes/:id/backlinks`) because only the server can see
 * every other note. Unresolved links are already on the note — a `LinkSummary` with no target —
 * so that half keeps working offline.
 */

export interface BacklinksPanelProps {
  readonly noteId: NoteId;
  readonly note: Note | null;
  readonly onOpenNote: (noteId: NoteId) => void;
  readonly onCreateNote: (title: string) => void;
}

export function BacklinksPanel({
  noteId,
  note,
  onOpenNote,
  onCreateNote,
}: BacklinksPanelProps): React.JSX.Element {
  const workspace = useWorkspace();
  const [backlinks, setBacklinks] = useState<readonly BacklinkSummary[]>([]);
  const [state, setState] = useState<'loading' | 'ready' | 'unavailable'>('loading');

  useEffect(() => {
    let cancelled = false;
    setState('loading');
    void (async () => {
      try {
        const found = await workspace.client.notes.backlinks(noteId);
        if (cancelled) return;
        setBacklinks(found);
        setState('ready');
      } catch {
        if (cancelled) return;
        setBacklinks([]);
        setState('unavailable');
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [noteId, workspace]);

  const unresolved = (note?.links ?? []).filter(
    (link) => link.targetNoteId === null && link.targetUrl === null,
  );

  return (
    <aside className="backlinks">
      <section className="backlinks__section">
        <h2 className="backlinks__heading">
          Linked from{state === 'ready' ? ` (${backlinks.length})` : ''}
        </h2>
        {state === 'loading' && <p className="backlinks__hint">Looking…</p>}
        {state === 'unavailable' && (
          <p className="backlinks__hint">
            Backlinks need the server. They will be here when it is reachable.
          </p>
        )}
        {state === 'ready' && backlinks.length === 0 && (
          <p className="backlinks__hint">Nothing links here yet.</p>
        )}
        <ul className="backlinks__list">
          {backlinks.map((backlink) => (
            <li key={`${backlink.sourceNoteId}:${backlink.kind}`}>
              <button
                className="backlinks__item"
                onClick={() => onOpenNote(backlink.sourceNoteId)}
                type="button"
              >
                <span className="backlinks__title">{displayTitle(backlink.sourceTitle)}</span>
                {backlink.context !== null && (
                  <span className="backlinks__context">{backlink.context}</span>
                )}
                {backlink.occurrences > 1 && (
                  <span className="backlinks__count">{backlink.occurrences}×</span>
                )}
              </button>
            </li>
          ))}
        </ul>
      </section>

      {unresolved.length > 0 && (
        <section className="backlinks__section">
          <h2 className="backlinks__heading">Not written yet ({unresolved.length})</h2>
          <p className="backlinks__hint">Links from this note to notes that do not exist.</p>
          <ul className="backlinks__list">
            {unresolved.map((link) => (
              <li key={link.targetTitle}>
                <button
                  className="backlinks__item backlinks__item--unresolved"
                  onClick={() => onCreateNote(link.targetTitle)}
                  type="button"
                >
                  <span className="backlinks__title">{link.targetTitle}</span>
                  <span className="backlinks__context">Create it</span>
                </button>
              </li>
            ))}
          </ul>
        </section>
      )}
    </aside>
  );
}
