import type { NoteId, TagName } from '@rosie-notes/schema';
import { useState } from 'react';
import { buildFilter, type FilterDraft } from '../filters/filter-draft';
import { useNoteQuery, useTags } from '../hooks/use-note-query';
import { routeToHash } from '../routing/routes';
import { FilterBar } from './filter-bar';
import { ResultList } from './result-list';
import { EmptyState, ErrorState, LoadingState, StaleBanner } from './states';

/**
 * Every tag, with counts, and the notes behind one of them.
 *
 * The counts are the reason this page exists rather than being a list of strings: a tag with two
 * notes and a tag with two hundred want different treatment, and you cannot tell which is which
 * from the name. Sorted by count, so the vocabulary you actually use is at the top.
 */

export interface TagsViewProps {
  readonly onOpenTag: (tag: TagName) => void;
}

export function TagsView({ onOpenTag }: TagsViewProps): React.JSX.Element {
  const { tags, loading, failed, reload } = useTags();
  const [needle, setNeedle] = useState('');

  const shown = tags.filter((tag) => tag.name.includes(needle.trim().toLowerCase()));
  const biggest = Math.max(1, ...tags.map((tag) => tag.noteCount));

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">Tags</h1>
        <span className="pane__subtitle">{tags.length} in use</span>
      </header>

      {failed && (
        <p className="pane__notice" role="status">
          Counted from this device’s cache — the server is not reachable, so a tag you have not
          touched here may be missing.
        </p>
      )}

      {loading && tags.length === 0 ? (
        <LoadingState label="Counting your tags…" />
      ) : tags.length === 0 ? (
        <EmptyState
          icon="🏷️"
          title="No tags yet"
          body="Write #like-this in a note, or add one from the note’s header."
          action={
            failed ? (
              <button className="button" onClick={reload} type="button">
                Try the server again
              </button>
            ) : undefined
          }
        />
      ) : (
        <>
          <input
            aria-label="Find a tag"
            className="filter-bar__text"
            onChange={(event) => setNeedle(event.target.value)}
            placeholder="Find a tag…"
            type="search"
            value={needle}
          />
          <ul className="tag-cloud">
            {shown.map((tag) => (
              <li key={tag.name}>
                <a
                  className="tag-cloud__item"
                  href={routeToHash({ name: 'tag', tag: tag.name })}
                  onClick={(event) => {
                    if (event.metaKey || event.ctrlKey || event.shiftKey) return;
                    event.preventDefault();
                    onOpenTag(tag.name);
                  }}
                  style={
                    tag.colour === null ? undefined : { borderColor: tag.colour, color: tag.colour }
                  }
                >
                  <span className="tag-cloud__name">#{tag.name}</span>
                  <span className="tag-cloud__count">{tag.noteCount}</span>
                  <span
                    aria-hidden="true"
                    className="tag-cloud__bar"
                    style={{ inlineSize: `${Math.round((tag.noteCount / biggest) * 100)}%` }}
                  />
                </a>
              </li>
            ))}
          </ul>
        </>
      )}
    </section>
  );
}

export interface TagViewProps {
  readonly tag: TagName;
  readonly draft: FilterDraft;
  readonly onDraftChange: (draft: FilterDraft) => void;
  readonly onOpenNote: (noteId: NoteId) => void;
}

export function TagView({
  tag,
  draft,
  onDraftChange,
  onOpenNote,
}: TagViewProps): React.JSX.Element {
  const extra = buildFilter(draft);
  const query = useNoteQuery({ tag, limit: 100, ...(extra === null ? {} : { filter: extra }) });

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">#{tag}</h1>
        <span className="pane__subtitle">
          {query.total ?? query.notes.length} note{query.notes.length === 1 ? '' : 's'}
        </span>
      </header>

      <FilterBar draft={draft} onChange={onDraftChange} />

      {query.stale && <StaleBanner reachable={query.error === null} />}

      {query.loading && query.notes.length === 0 ? (
        <LoadingState label={`Fetching notes tagged #${tag}…`} />
      ) : query.notes.length === 0 ? (
        query.error !== null ? (
          <ErrorState
            title="Could not load these notes"
            body="Nothing matching is cached on this device either."
            onRetry={query.reload}
          />
        ) : (
          <EmptyState icon="🏷️" title={`Nothing is tagged #${tag} right now`} />
        )
      ) : (
        <ResultList notes={query.notes} onOpenNote={onOpenNote} />
      )}

      {query.hasMore && (
        <button className="button" onClick={query.loadMore} type="button">
          Load more
        </button>
      )}
    </section>
  );
}
