import { type ReactNode, useEffect, useId, useRef } from 'react';

/**
 * A dialog.
 *
 * Deliberately not `<dialog showModal>`: jsdom does not implement it, so every test touching a
 * dialog would need a polyfill, and the three behaviours that actually matter — Escape closes,
 * a click on the scrim closes, and focus starts inside — are a dozen lines. Focus is *moved in*
 * but not trapped; a trap that is subtly wrong is worse than none, and every dialog here is
 * dismissible with one key.
 */

export interface ModalProps {
  readonly title: string;
  readonly onClose: () => void;
  readonly children: ReactNode;
  /** Wider layout for the palette, which is a list rather than a form. */
  readonly variant?: 'panel' | 'palette';
}

export function Modal({
  title,
  onClose,
  children,
  variant = 'panel',
}: ModalProps): React.JSX.Element {
  const surfaceRef = useRef<HTMLDivElement | null>(null);
  const titleId = useId();

  useEffect(() => {
    const previous = document.activeElement;
    const focusable = surfaceRef.current?.querySelector<HTMLElement>(
      'input, button, select, textarea, [tabindex]:not([tabindex="-1"])',
    );
    focusable?.focus();

    function onKeyDown(event: KeyboardEvent): void {
      if (event.key === 'Escape') {
        event.preventDefault();
        onClose();
      }
    }
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      if (previous instanceof HTMLElement) {
        previous.focus();
      }
    };
  }, [onClose]);

  return (
    <div className="modal">
      {/* The scrim is a dismiss affordance for the pointer; Escape is the keyboard one, so this
          element is deliberately not focusable and carries no role. */}
      {/* biome-ignore lint/a11y/noStaticElementInteractions: keyboard path is the Escape handler */}
      {/* biome-ignore lint/a11y/useKeyWithClickEvents: keyboard path is the Escape handler */}
      <div className="modal__scrim" onClick={onClose} />
      <div
        aria-labelledby={titleId}
        aria-modal="true"
        className={`modal__surface modal__surface--${variant}`}
        ref={surfaceRef}
        role="dialog"
      >
        <header className="modal__header">
          <h2 className="modal__title" id={titleId}>
            {title}
          </h2>
          <button aria-label="Close" className="modal__close" onClick={onClose} type="button">
            ×
          </button>
        </header>
        <div className="modal__content">{children}</div>
      </div>
    </div>
  );
}
