import { isClientError, type NotesClientError } from '@rosie-notes/client';
import type { Collection, Note, NoteListRequestInput, Page, Tag } from '@rosie-notes/schema';
import { useCallback, useEffect, useRef, useState } from 'react';
import { filterNotes } from '../filters/evaluate';
import { useWorkspace } from '../session/session-context';

/**
 * A scoped listing: the trash, a collection, one tag, everything of one kind.
 *
 * Separate from `NotesStore` on purpose. The store holds *the library* — the thing the sidebar
 * and the wiki-link picker read — and a view that replaced it every time somebody clicked a tag
 * would make the sidebar jump around and lose whatever the editor was mid-way through.
 *
 * Offline is not an error state here either: when the request fails because the server is
 * unreachable, the same filter is run over the cached notes by `filters/evaluate`, the result is
 * marked `stale`, and the view draws it. Only a failure with nothing cached is worth an error.
 */

export interface NoteQueryState {
  readonly notes: readonly Note[];
  readonly loading: boolean;
  readonly error: NotesClientError | null;
  /** These came from the cache, not from the server. */
  readonly stale: boolean;
  readonly hasMore: boolean;
  readonly total: number | null;
}

export interface NoteQueryResult extends NoteQueryState {
  reload(): void;
  loadMore(): void;
}

const EMPTY: NoteQueryState = {
  notes: [],
  loading: true,
  error: null,
  stale: false,
  hasMore: false,
  total: null,
};

export function useNoteQuery(request: NoteListRequestInput): NoteQueryResult {
  const workspace = useWorkspace();
  const [state, setState] = useState<NoteQueryState>(EMPTY);
  const [nonce, setNonce] = useState(0);
  const cursorRef = useRef<string | null>(null);

  // The request is a fresh object on every render; its *content* is what identifies the query.
  const key = JSON.stringify(request);

  // `nonce` is not read in the body — it is the reload signal. Bumping it is how `reload()`
  // re-runs a query whose inputs have not changed, which is the entire point of a retry button.
  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    let cancelled = false;
    const query = JSON.parse(key) as NoteListRequestInput;
    cursorRef.current = null;
    setState((previous) => ({ ...previous, loading: true }));

    void (async () => {
      try {
        const page = await workspace.client.notes.list(query);
        if (cancelled) return;
        cursorRef.current = page.nextCursor;
        // Cache what came back, so the next cold start — or the next disconnection — has it.
        for (const item of page.items) {
          void workspace.adapter.cache.writeNote(item);
        }
        setState({
          notes: page.items,
          loading: false,
          error: null,
          stale: false,
          hasMore: page.hasMore,
          total: page.total,
        });
      } catch (error) {
        if (cancelled) return;
        const cached = await workspace.adapter.cache.listNotes();
        if (cancelled) return;
        const local = filterNotes(cached, {
          filter: query.filter ?? null,
          ...(query.sort === undefined ? {} : { sort: query.sort }),
          ...(query.limit === undefined ? {} : { limit: query.limit }),
        }).filter((note) => matchesShorthand(note, query));
        setState({
          notes: local,
          loading: false,
          // An empty *cache* is a failure to answer at all, and gets an error state with a retry.
          // A cache that answered and found nothing matching is not a failure — it is an answer,
          // and dressing it up as an error would teach people to distrust a correct empty screen.
          error: cached.length === 0 && isClientError(error) ? error : null,
          stale: true,
          hasMore: false,
          total: null,
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [key, workspace, nonce]);

  const reload = useCallback(() => setNonce((value) => value + 1), []);

  const loadMore = useCallback(() => {
    const cursor = cursorRef.current;
    if (cursor === null) {
      return;
    }
    void (async () => {
      try {
        const query = { ...(JSON.parse(key) as NoteListRequestInput), cursor };
        const page: Page<Note> = await workspace.client.notes.list(query);
        cursorRef.current = page.nextCursor;
        setState((previous) => ({
          ...previous,
          notes: [...previous.notes, ...page.items],
          hasMore: page.hasMore,
        }));
      } catch {
        // The button simply does nothing more; what is already listed stays listed.
      }
    })();
  }, [key, workspace]);

  return { ...state, reload, loadMore };
}

/** The list endpoint's convenience parameters, applied locally for the offline fallback. */
function matchesShorthand(note: Note, query: NoteListRequestInput): boolean {
  if (query.kind !== undefined && note.kind !== query.kind) {
    return false;
  }
  if (query.tag !== undefined && !note.tags.includes(query.tag)) {
    return false;
  }
  if (query.collectionId !== undefined && !note.collectionIds.includes(query.collectionId)) {
    return false;
  }
  if (query.parentId !== undefined && note.parentId !== (query.parentId ?? null)) {
    return false;
  }
  return true;
}

export interface TagsState {
  readonly tags: readonly Tag[];
  readonly loading: boolean;
  readonly failed: boolean;
  reload(): void;
}

/** Every tag with its live note count — the picker, the sidebar and the tag page all use this. */
export function useTags(): TagsState {
  const workspace = useWorkspace();
  const [tags, setTags] = useState<readonly Tag[]>([]);
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);
  const [nonce, setNonce] = useState(0);

  // `nonce` is not read in the body — it is the reload signal. Bumping it is how `reload()`
  // re-runs a query whose inputs have not changed, which is the entire point of a retry button.
  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const page = await workspace.client.tags.list({ limit: 200, sort: 'noteCount' });
        if (cancelled) return;
        setTags(page.items);
        setFailed(false);
      } catch {
        if (cancelled) return;
        // Fall back to whatever the cached notes carry, so the picker still offers something.
        const cached = await workspace.adapter.cache.listNotes();
        if (cancelled) return;
        setTags(tagsFromNotes(cached));
        setFailed(true);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspace, nonce]);

  return { tags, loading, failed, reload: useCallback(() => setNonce((v) => v + 1), []) };
}

/**
 * Tags reconstructed from cached notes. Not real `Tag` rows — no ids, no colours — but the count
 * is right and the names are right, which is all the picker needs while offline.
 */
function tagsFromNotes(notes: readonly Note[]): Tag[] {
  const counts = new Map<string, number>();
  for (const note of notes) {
    if (note.trashed) continue;
    for (const tag of note.tags) {
      counts.set(tag, (counts.get(tag) ?? 0) + 1);
    }
  }
  const now = new Date(0).toISOString();
  return [...counts.entries()]
    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
    .map(([name, noteCount]) => ({
      id: `offline:${name}` as Tag['id'],
      ownerId: '' as Tag['ownerId'],
      name: name as Tag['name'],
      colour: null,
      description: null,
      noteCount,
      createdAt: now,
      updatedAt: now,
    }));
}

export interface CollectionsState {
  readonly collections: readonly Collection[];
  readonly loading: boolean;
  readonly failed: boolean;
  reload(): void;
}

export function useCollections(): CollectionsState {
  const workspace = useWorkspace();
  const [collections, setCollections] = useState<readonly Collection[]>([]);
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);
  const [nonce, setNonce] = useState(0);

  // `nonce` is not read in the body — it is the reload signal. Bumping it is how `reload()`
  // re-runs a query whose inputs have not changed, which is the entire point of a retry button.
  // biome-ignore lint/correctness/useExhaustiveDependencies: nonce is a deliberate re-run trigger
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    void (async () => {
      try {
        const page = await workspace.client.collections.list({ limit: 200 });
        if (cancelled) return;
        setCollections(page.items);
        setFailed(false);
      } catch {
        if (!cancelled) setFailed(true);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [workspace, nonce]);

  return {
    collections,
    loading,
    failed,
    reload: useCallback(() => setNonce((v) => v + 1), []),
  };
}
