import type { ReactNode } from 'react';

/**
 * Empty, loading and error, written once.
 *
 * A blank screen is a bug that looks like a design decision, and a bare spinner is a promise
 * with no expiry date. Every list and pane in this app uses one of these three, so there is
 * nowhere left for an unexplained void to appear.
 */

export interface EmptyStateProps {
  readonly icon?: string;
  readonly title: string;
  readonly body?: ReactNode;
  readonly action?: ReactNode;
}

export function EmptyState({ icon, title, body, action }: EmptyStateProps): React.JSX.Element {
  return (
    <div className="state state--empty">
      {icon !== undefined && (
        <span aria-hidden="true" className="state__icon">
          {icon}
        </span>
      )}
      <p className="state__title">{title}</p>
      {body !== undefined && <p className="state__body">{body}</p>}
      {action !== undefined && <div className="state__action">{action}</div>}
    </div>
  );
}

export interface LoadingStateProps {
  /** Say what is being waited for. "Loading…" on its own tells nobody anything. */
  readonly label: string;
}

export function LoadingState({ label }: LoadingStateProps): React.JSX.Element {
  return (
    <div aria-busy="true" className="state state--loading" role="status">
      <span aria-hidden="true" className="spinner" />
      <p className="state__body">{label}</p>
    </div>
  );
}

export interface ErrorStateProps {
  readonly title: string;
  readonly body?: ReactNode;
  readonly onRetry?: () => void;
}

export function ErrorState({ title, body, onRetry }: ErrorStateProps): React.JSX.Element {
  return (
    <div className="state state--error" role="alert">
      <span aria-hidden="true" className="state__icon">
        ⚠️
      </span>
      <p className="state__title">{title}</p>
      {body !== undefined && <p className="state__body">{body}</p>}
      {onRetry !== undefined && (
        <div className="state__action">
          <button className="button" onClick={onRetry} type="button">
            Try again
          </button>
        </div>
      )}
    </div>
  );
}

/** The one-line "these are cached" banner. Content stays on screen; only the label is added. */
export function StaleBanner({ reachable }: { readonly reachable: boolean }): React.JSX.Element {
  return (
    <p className="stale-banner" role="status">
      <span aria-hidden="true">⛅</span> Showing the last copy on this device
      {reachable ? '…' : ' — the server is not reachable.'}
    </p>
  );
}
