import type { NoteKind } from '@rosie-notes/schema';

/**
 * What each note kind looks like and is called.
 *
 * The kind is a first-class filter dimension in the schema, not decoration, so it needs to be
 * legible at a glance in a list of two hundred notes. A glyph does that in one character; a
 * coloured dot does not, because "which colour was `prompt` again" is not a question anybody
 * should have to answer.
 */

export const NOTE_KINDS: readonly NoteKind[] = [
  'page',
  'project',
  'idea',
  'prompt',
  'doc',
  'source',
  'snippet',
  'story',
  'voice',
];

interface KindPresentation {
  readonly icon: string;
  readonly label: string;
  readonly hint: string;
}

const PRESENTATION: Record<NoteKind, KindPresentation> = {
  page: { icon: '📄', label: 'Page', hint: 'A plain note — the default.' },
  project: { icon: '🧩', label: 'Project', hint: 'The hub note for a codebase.' },
  idea: { icon: '💡', label: 'Idea', hint: 'A rough capture, deliberately low-friction.' },
  prompt: { icon: '✨', label: 'Prompt', hint: 'Text meant to be fed to a model.' },
  doc: { icon: '📘', label: 'Doc', hint: 'Reference documentation you wrote.' },
  source: { icon: '🔗', label: 'Source', hint: 'Something external you are tracking.' },
  snippet: { icon: '🧾', label: 'Snippet', hint: 'A code fragment, copy-first.' },
  story: { icon: '📖', label: 'Story', hint: 'An entry in a browsable library.' },
  voice: { icon: '🎙️', label: 'Voice', hint: 'A recording and its transcript.' },
};

export function kindIcon(kind: NoteKind): string {
  return PRESENTATION[kind].icon;
}

export function kindLabel(kind: NoteKind): string {
  return PRESENTATION[kind].label;
}

export function kindHint(kind: NoteKind): string {
  return PRESENTATION[kind].hint;
}

/** `Untitled` rather than an empty row: a note with no title still has to be clickable. */
export function displayTitle(title: string): string {
  const trimmed = title.trim();
  return trimmed === '' ? 'Untitled' : trimmed;
}

/** A short, relative-ish timestamp. Long enough to be unambiguous, short enough for a list. */
export function shortWhen(iso: string, now: number = Date.now()): string {
  const at = new Date(iso);
  const days = (now - at.getTime()) / 86_400_000;
  if (Number.isNaN(days)) {
    return '';
  }
  if (days < 1) {
    return at.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  }
  if (days < 365) {
    return at.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
  }
  return at.toLocaleDateString(undefined, { year: 'numeric', month: 'short' });
}
