import {
  CAPABILITY_PRESETS,
  createDirectTransportPair,
  type EditorHandle,
  HostBridge,
  mountEditor,
} from '@rosie-notes/editor';
import type { NoteId } from '@rosie-notes/schema';
import { type ThemeMode, toThemePayload } from '@rosie-notes/tokens';
import { useEffect, useRef, useState } from 'react';
import { filterNotes } from '../filters/evaluate';
import { isDeliveryFailure } from '../offline/write-queue';
import { useWorkspace } from '../session/session-context';

/**
 * The editor pane.
 *
 * Three things meet here, and the join is the interesting part:
 *
 * - **the shared editor bundle**, mounted with a `direct` transport because the web app and the
 *   editor share a realm. It still serialises every message through the real codec, so a bridge
 *   bug is reproducible here rather than only on a phone.
 * - **the note's `Y.Doc`**, which the sync engine already owns and is already watching. Handing
 *   the same document to the {@link HostBridge} means a keystroke goes editor → host → outbox →
 *   server with no code in between, and a change from another device arrives by the same path
 *   backwards.
 * - **the note's markdown body**, pushed to the server on a debounce so search has something to
 *   index. The CRDT is the source of truth for the *text*; the body column is a projection of it.
 *
 * Mounting is keyed on the note id and torn down completely when it changes. Reusing one editor
 * across documents is how stale-Yjs-state bugs happen, and a note switch is not a hot path.
 *
 * ## The three bridge callbacks
 *
 * `notes:query`, `notes:open` and `notes:create` are what make `[[wiki-links]]` real rather than
 * decorative, and all three are wired to the actual application: the picker searches the server
 * (falling back to the cache when it cannot), clicking a resolved link navigates, and clicking an
 * unresolved one *creates the note* with that title and opens it. A link you have not written yet
 * is the normal way a project note grows.
 */

/** Long enough that typing does not spam the API; short enough to survive a closed tab. */
const BODY_SAVE_DELAY_MS = 2_000;

/** What the indicator in the note header says. */
export type SaveState = 'idle' | 'dirty' | 'saving' | 'saved' | 'offline' | 'error';

export interface NoteEditorProps {
  readonly noteId: NoteId;
  readonly theme: ThemeMode;
  readonly readOnly?: boolean;
  readonly onOpenNote?: (noteId: NoteId) => void;
  /** Called with a title when an unresolved `[[link]]` is followed. Should create and open it. */
  readonly onCreateNote?: (title: string) => void;
  readonly onSaveStateChange?: (state: SaveState) => void;
}

export function NoteEditor({
  noteId,
  theme,
  readOnly = false,
  onOpenNote,
  onCreateNote,
  onSaveStateChange,
}: NoteEditorProps): React.JSX.Element {
  const workspace = useWorkspace();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const bridgeRef = useRef<HostBridge | null>(null);
  const [status, setStatus] = useState<'loading' | 'ready' | 'failed'>('loading');
  const [failure, setFailure] = useState<string | null>(null);

  // Held in refs so changing a callback never remounts the editor — a remount mid-sentence would
  // lose the caret, and these change identity on nearly every render of the parent.
  const openRef = useRef(onOpenNote);
  const createRef = useRef(onCreateNote);
  const saveStateRef = useRef(onSaveStateChange);
  openRef.current = onOpenNote;
  createRef.current = onCreateNote;
  saveStateRef.current = onSaveStateChange;

  useEffect(() => {
    const container = containerRef.current;
    if (container === null) {
      return;
    }

    let disposed = false;
    let handle: EditorHandle | null = null;
    let bridge: HostBridge | null = null;
    let saveTimer: ReturnType<typeof setTimeout> | null = null;
    let lastSavedBody: string | null = null;

    // Reporting stops the instant the effect is torn down: a save that lands after the user has
    // moved on must not relabel the *next* note as saved.
    const report = (state: SaveState): void => {
      if (!disposed) saveStateRef.current?.(state);
    };

    async function saveBody(): Promise<void> {
      const live = bridge;
      if (live === null) return;
      try {
        const markdown = await live.requestMarkdown();
        if (markdown === lastSavedBody) {
          report('saved');
          return;
        }
        report('saving');
        lastSavedBody = markdown;
        await workspace.store.updateNote(noteId, {
          body: { format: 'markdown', text: markdown },
        });
        report('saved');
      } catch (error) {
        // Offline, or the editor is mid-teardown. The CRDT still holds the text and the outbox
        // still holds the update, so nothing is lost — only the search index lags.
        lastSavedBody = null;
        report(isDeliveryFailure(error) ? 'offline' : 'error');
      }
    }

    function scheduleSave(): void {
      report('dirty');
      if (saveTimer !== null) clearTimeout(saveTimer);
      saveTimer = setTimeout(() => {
        saveTimer = null;
        void saveBody();
      }, BODY_SAVE_DELAY_MS);
    }

    async function mount(): Promise<void> {
      try {
        // `open` rehydrates from the local cache and starts watching for local edits, so the
        // editor's first paint does not wait on the network.
        const note = await workspace.engine.open(noteId);
        if (disposed) return;

        const pair = createDirectTransportPair();

        bridge = new HostBridge({
          transport: pair.host,
          noteId,
          doc: note.doc,
          theme: toThemePayload(theme),
          capabilities: CAPABILITY_PRESETS.web,
          readOnly,
          placeholder: 'Write something, or press / for blocks…',
          handlers: {
            openLink: (href) => {
              globalThis.open(href, '_blank', 'noopener,noreferrer');
            },
            openNote: (linked) => openRef.current?.(linked as NoteId),
            createNote: (title) => createRef.current?.(title),
            queryNotes: async (query, limit) => {
              const trimmed = query.trim();
              try {
                const response = await workspace.store.search({
                  ...(trimmed === '' ? { filter: { type: 'all' } } : { query: trimmed }),
                  limit,
                });
                return response.items.map((hit) => ({
                  noteId: hit.note.id,
                  title: hit.note.title,
                  kind: hit.note.kind,
                  excerpt: hit.note.excerpt,
                }));
              } catch {
                // Offline: the picker still has to offer something, and the cache is right there.
                const cached = await workspace.adapter.cache.listNotes();
                return filterNotes(cached, {
                  filter: trimmed === '' ? null : { type: 'text', query: trimmed, field: 'all' },
                  limit,
                }).map((note) => ({
                  noteId: note.id,
                  title: note.title,
                  kind: note.kind,
                  excerpt: note.excerpt,
                }));
              }
            },
          },
        });
        bridgeRef.current = bridge;
        bridge.start();

        handle = mountEditor(container as HTMLElement, pair.editor, {
          theme: toThemePayload(theme),
        });
        // Any change to the document — typed here or arrived from another device — means the
        // markdown projection is out of date.
        note.doc.on('updateV2', scheduleSave);

        if (disposed) return;
        setStatus('ready');
        report('idle');

        // Catch up with the server in the background; the cached document is already on screen.
        void workspace.engine.pull(noteId).catch(() => undefined);
      } catch (error) {
        if (disposed) return;
        setFailure(error instanceof Error ? error.message : String(error));
        setStatus('failed');
      }
    }

    void mount();

    return () => {
      if (saveTimer !== null) clearTimeout(saveTimer);
      const note = workspace.engine.doc(noteId);
      note?.doc.off('updateV2', scheduleSave);
      // Save what is there before the bridge goes — this is the last chance to project the body —
      // and only then tear the editor down. `disposed` is set after the save is *requested*, so
      // the request still reaches a live bridge but nothing it returns touches the new note.
      const pending = saveBody();
      disposed = true;
      void pending.finally(() => {
        handle?.destroy();
        bridge?.dispose();
        bridgeRef.current = null;
      });
    };
  }, [workspace, noteId, theme, readOnly]);

  // Theme changes do not remount — the bridge can push a new one.
  useEffect(() => {
    bridgeRef.current?.setTheme(toThemePayload(theme));
  }, [theme]);

  return (
    <div className="note-editor">
      {status === 'failed' && (
        <p className="note-editor__failure" role="alert">
          This note could not be opened. {failure}
        </p>
      )}
      {status === 'loading' && (
        <p className="note-editor__loading" role="status">
          Opening the note…
        </p>
      )}
      <div
        className="note-editor__surface"
        data-status={status}
        ref={containerRef}
        // The editor manages this subtree itself; React must not try to reconcile it.
        suppressHydrationWarning
      />
    </div>
  );
}
