import { type TagName, TagNameSchema } from '@rosie-notes/schema';
import { useId, useState } from 'react';
import { useTags } from '../hooks/use-note-query';

/**
 * The tag editor on a note.
 *
 * Tag names are constrained by the schema — lowercase, no spaces, `/` for hierarchy — so the
 * input validates against `TagNameSchema` itself rather than reimplementing the rule. A typed
 * `Rust Async` is offered back as `rust-async` instead of being rejected: the useful thing to do
 * with a near-miss is fix it, not refuse it.
 */

export interface TagInputProps {
  readonly tags: readonly TagName[];
  readonly onChange: (tags: readonly TagName[]) => void;
  readonly disabled?: boolean;
}

/** Best-effort repair of a typed tag. Returns `null` when there is nothing salvageable. */
export function normaliseTag(raw: string): TagName | null {
  const candidate = raw
    .trim()
    .toLowerCase()
    .replace(/^#/, '')
    .replace(/\s+/gu, '-')
    .replace(/[^a-z0-9/_.-]/gu, '');
  const parsed = TagNameSchema.safeParse(candidate);
  return parsed.success ? parsed.data : null;
}

export function TagInput({ tags, onChange, disabled = false }: TagInputProps): React.JSX.Element {
  const [draft, setDraft] = useState('');
  const [problem, setProblem] = useState<string | null>(null);
  const listId = useId();
  const { tags: known } = useTags();

  function add(raw: string): void {
    const tag = normaliseTag(raw);
    if (tag === null) {
      setProblem('Tags are lowercase, without spaces; use / for hierarchy.');
      return;
    }
    setProblem(null);
    setDraft('');
    if (!tags.includes(tag)) {
      onChange([...tags, tag]);
    }
  }

  return (
    <div className="tag-input">
      <ul className="tag-input__tags">
        {tags.map((tag) => (
          <li key={tag}>
            <span className="chip chip--tag">
              #{tag}
              <button
                aria-label={`Remove tag ${tag}`}
                className="chip__remove"
                disabled={disabled}
                onClick={() => onChange(tags.filter((value) => value !== tag))}
                type="button"
              >
                ×
              </button>
            </span>
          </li>
        ))}
      </ul>
      <input
        aria-label="Add a tag"
        className="tag-input__field"
        disabled={disabled}
        list={listId}
        onBlur={() => {
          if (draft.trim() !== '') add(draft);
        }}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ',') {
            event.preventDefault();
            add(draft);
          }
          if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
            onChange(tags.slice(0, -1));
          }
        }}
        placeholder="add tag…"
        value={draft}
      />
      <datalist id={listId}>
        {known.map((tag) => (
          <option key={tag.name} value={tag.name}>
            {tag.noteCount} notes
          </option>
        ))}
      </datalist>
      {problem !== null && (
        <p className="tag-input__problem" role="alert">
          {problem}
        </p>
      )}
    </div>
  );
}
