import type {
  CollectionId,
  DateField,
  Filter,
  HasTarget,
  NoteKind,
  TagName,
  TextField,
} from '@rosie-notes/schema';

/**
 * The filter UI, as data.
 *
 * The filter bar edits a {@link FilterDraft} — a flat record of exactly what the controls show —
 * and {@link buildFilter} turns it into the `Filter` AST from `@rosie-notes/schema`. Keeping the
 * two apart is what makes the interesting half testable without a DOM: a UI test can assert the
 * *object* a set of controls produces, and the server, the smart collections and the offline
 * evaluator all consume that same object.
 *
 * The draft is deliberately not the AST. A half-typed date, an empty tag list and "no opinion"
 * are all representable here and none of them are representable in the AST — which is the point,
 * because the AST is the thing that has to be valid.
 */

/** No opinion / require / exclude. Maps onto a `flag` node, or onto nothing at all. */
export type TriState = 'any' | 'yes' | 'no';

export interface FilterDraft {
  /** Free text. Empty means no `text` node. */
  readonly text: string;
  readonly textField: TextField;
  readonly tags: readonly TagName[];
  readonly kinds: readonly NoteKind[];
  /** Which timestamp the date range applies to. */
  readonly dateField: DateField;
  /** `YYYY-MM-DD`, as an `<input type="date">` gives it. Empty means unbounded. */
  readonly after: string;
  readonly before: string;
  /** `null` means "do not care whether the note has attachments". */
  readonly has: HasTarget | null;
  readonly pinned: TriState;
  readonly archived: TriState;
  readonly trashed: TriState;
  readonly collectionId: CollectionId | null;
}

export const EMPTY_FILTER_DRAFT: FilterDraft = {
  text: '',
  textField: 'all',
  tags: [],
  kinds: [],
  dateField: 'updated',
  after: '',
  before: '',
  has: null,
  pinned: 'any',
  archived: 'any',
  trashed: 'any',
  collectionId: null,
};

/** True when nothing in the draft would narrow anything. */
export function isEmptyDraft(draft: FilterDraft): boolean {
  return buildFilter(draft) === null;
}

/** How many separate conditions the draft carries — the number on the "Filters" button. */
export function activeClauseCount(draft: FilterDraft): number {
  const built = buildFilter(draft);
  if (built === null) {
    return 0;
  }
  return built.type === 'and' ? built.filters.length : 1;
}

/**
 * `2026-08-01` -> `2026-08-01T00:00:00.000Z` for `after`, and the last instant of the day for
 * `before`. Both bounds are therefore inclusive of the day the user picked, which is what
 * "between the 1st and the 3rd" means to everybody who is not a database.
 */
function startOfDay(date: string): string {
  return `${date}T00:00:00.000Z`;
}

function endOfDay(date: string): string {
  return `${date}T23:59:59.999Z`;
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function flagNode(flag: 'pinned' | 'archived' | 'trashed', state: TriState): Filter | null {
  if (state === 'any') {
    return null;
  }
  return { type: 'flag', flag, value: state === 'yes' };
}

/**
 * Turn the draft into a `Filter`, or `null` when it says nothing.
 *
 * Rules worth knowing at the call sites:
 *
 * - several tags are ANDed (a note must carry all of them), several kinds are ORed (a note is one
 *   kind, so ANDing them would match nothing);
 * - a single condition is returned bare rather than wrapped in a pointless one-child `and`;
 * - `null` means "no filter", which callers send as an absent `filter` rather than as
 *   `{ type: 'all' }` — the server's own default (exclude trashed) then applies.
 */
export function buildFilter(draft: FilterDraft): Filter | null {
  const clauses: Filter[] = [];

  const text = draft.text.trim();
  if (text !== '') {
    clauses.push({ type: 'text', query: text.slice(0, 512), field: draft.textField });
  }

  for (const tag of draft.tags) {
    clauses.push({ type: 'tag', tag });
  }

  const kinds = draft.kinds;
  if (kinds.length === 1) {
    const [only] = kinds;
    if (only !== undefined) {
      clauses.push({ type: 'kind', kind: only });
    }
  } else if (kinds.length > 1) {
    clauses.push({
      type: 'or',
      filters: kinds.map((kind): Filter => ({ type: 'kind', kind })),
    });
  }

  if (ISO_DATE.test(draft.after)) {
    clauses.push({
      type: 'date',
      field: draft.dateField,
      op: 'after',
      value: startOfDay(draft.after),
    });
  }
  if (ISO_DATE.test(draft.before)) {
    clauses.push({
      type: 'date',
      field: draft.dateField,
      op: 'before',
      value: endOfDay(draft.before),
    });
  }

  if (draft.has !== null) {
    clauses.push({ type: 'has', target: draft.has });
  }

  if (draft.collectionId !== null) {
    clauses.push({ type: 'collection', collectionId: draft.collectionId });
  }

  for (const [flag, state] of [
    ['pinned', draft.pinned],
    ['archived', draft.archived],
    ['trashed', draft.trashed],
  ] as const) {
    const node = flagNode(flag, state);
    if (node !== null) {
      clauses.push(node);
    }
  }

  if (clauses.length === 0) {
    return null;
  }
  if (clauses.length === 1) {
    return clauses[0] ?? null;
  }
  return { type: 'and', filters: clauses };
}

/** AND two filters, skipping the wrapper when one of them is absent. */
export function combineFilters(left: Filter | null, right: Filter | null): Filter | null {
  if (left === null) {
    return right;
  }
  if (right === null) {
    return left;
  }
  const flatten = (filter: Filter): Filter[] => (filter.type === 'and' ? filter.filters : [filter]);
  return { type: 'and', filters: [...flatten(left), ...flatten(right)] };
}

/** One short human-readable line per condition — what the filter chips say. */
export function describeDraft(draft: FilterDraft): string[] {
  const parts: string[] = [];
  const text = draft.text.trim();
  if (text !== '') {
    parts.push(draft.textField === 'all' ? `“${text}”` : `${draft.textField}: “${text}”`);
  }
  for (const tag of draft.tags) {
    parts.push(`#${tag}`);
  }
  if (draft.kinds.length > 0) {
    parts.push(draft.kinds.join(' or '));
  }
  if (ISO_DATE.test(draft.after)) {
    parts.push(`${draft.dateField} after ${draft.after}`);
  }
  if (ISO_DATE.test(draft.before)) {
    parts.push(`${draft.dateField} before ${draft.before}`);
  }
  if (draft.has !== null) {
    parts.push(`has ${draft.has}`);
  }
  for (const [label, state] of [
    ['pinned', draft.pinned],
    ['archived', draft.archived],
    ['trashed', draft.trashed],
  ] as const) {
    if (state !== 'any') {
      parts.push(state === 'yes' ? label : `not ${label}`);
    }
  }
  return parts;
}
