import type { HasTarget, NoteKind, TagName, TextField } from '@rosie-notes/schema';
import { useId, useState } from 'react';
import {
  activeClauseCount,
  describeDraft,
  EMPTY_FILTER_DRAFT,
  type FilterDraft,
  type TriState,
} from '../filters/filter-draft';
import { useTags } from '../hooks/use-note-query';
import { kindIcon, kindLabel, NOTE_KINDS } from './kinds';

/**
 * The filter builder.
 *
 * Every control here edits one field of a {@link FilterDraft}; `buildFilter` turns the draft into
 * the `Filter` AST the server compiles, the smart collections store and the offline evaluator
 * runs. The UI therefore has no opinion about what a filter *is* — it cannot invent a condition
 * the rest of the system does not understand, and the tests assert on the AST rather than on the
 * markup.
 */

const HAS_TARGETS: readonly { value: HasTarget; label: string }[] = [
  { value: 'file', label: 'any attachment' },
  { value: 'image', label: 'an image' },
  { value: 'audio', label: 'audio' },
  { value: 'video', label: 'video' },
  { value: 'link', label: 'an outgoing link' },
  { value: 'backlink', label: 'a backlink' },
];

const TEXT_FIELDS: readonly { value: TextField; label: string }[] = [
  { value: 'all', label: 'anywhere' },
  { value: 'title', label: 'in the title' },
  { value: 'body', label: 'in the body' },
];

export interface FilterBarProps {
  readonly draft: FilterDraft;
  readonly onChange: (draft: FilterDraft) => void;
  /** Hidden where the route already implies it — the trash does not need a `trashed` control. */
  readonly hideFlags?: boolean;
}

export function FilterBar({
  draft,
  onChange,
  hideFlags = false,
}: FilterBarProps): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const { tags } = useTags();
  const panelId = useId();
  const count = activeClauseCount(draft);
  const chips = describeDraft(draft);

  function patch(changes: Partial<FilterDraft>): void {
    onChange({ ...draft, ...changes });
  }

  function toggleKind(kind: NoteKind): void {
    patch({
      kinds: draft.kinds.includes(kind)
        ? draft.kinds.filter((value) => value !== kind)
        : [...draft.kinds, kind],
    });
  }

  function toggleTag(tag: TagName): void {
    patch({
      tags: draft.tags.includes(tag)
        ? draft.tags.filter((value) => value !== tag)
        : [...draft.tags, tag],
    });
  }

  return (
    <div className="filter-bar">
      <div className="filter-bar__row">
        <input
          aria-label="Filter by text"
          className="filter-bar__text"
          onChange={(event) => patch({ text: event.target.value })}
          placeholder="Filter these notes…"
          type="search"
          value={draft.text}
        />
        <button
          aria-controls={panelId}
          aria-expanded={open}
          className="button button--quiet filter-bar__toggle"
          onClick={() => setOpen(!open)}
          type="button"
        >
          Filters{count === 0 ? '' : ` (${count})`}
        </button>
        {count > 0 && (
          <button
            className="button button--quiet"
            onClick={() => onChange(EMPTY_FILTER_DRAFT)}
            type="button"
          >
            Clear
          </button>
        )}
      </div>

      {chips.length > 0 && !open && (
        <ul className="filter-bar__chips">
          {chips.map((chip) => (
            <li className="chip" key={chip}>
              {chip}
            </li>
          ))}
        </ul>
      )}

      {open && (
        <div className="filter-panel" id={panelId}>
          <fieldset className="filter-panel__group">
            <legend className="filter-panel__legend">Text</legend>
            <select
              aria-label="Where to look for the text"
              className="filter-panel__select"
              onChange={(event) => patch({ textField: event.target.value as TextField })}
              value={draft.textField}
            >
              {TEXT_FIELDS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </fieldset>

          <fieldset className="filter-panel__group">
            <legend className="filter-panel__legend">Kind</legend>
            <div className="filter-panel__options">
              {NOTE_KINDS.map((kind) => (
                <button
                  aria-pressed={draft.kinds.includes(kind)}
                  className="toggle-chip"
                  key={kind}
                  onClick={() => toggleKind(kind)}
                  type="button"
                >
                  <span aria-hidden="true">{kindIcon(kind)}</span> {kindLabel(kind)}
                </button>
              ))}
            </div>
          </fieldset>

          <fieldset className="filter-panel__group">
            <legend className="filter-panel__legend">Tags</legend>
            {tags.length === 0 ? (
              <p className="filter-panel__hint">No tags yet.</p>
            ) : (
              <div className="filter-panel__options">
                {tags.slice(0, 40).map((tag) => (
                  <button
                    aria-pressed={draft.tags.includes(tag.name)}
                    className="toggle-chip"
                    key={tag.name}
                    onClick={() => toggleTag(tag.name)}
                    type="button"
                  >
                    #{tag.name}
                    <span className="toggle-chip__count">{tag.noteCount}</span>
                  </button>
                ))}
              </div>
            )}
          </fieldset>

          <fieldset className="filter-panel__group">
            <legend className="filter-panel__legend">Dates</legend>
            <div className="filter-panel__row">
              <select
                aria-label="Which date"
                className="filter-panel__select"
                onChange={(event) =>
                  patch({ dateField: event.target.value === 'created' ? 'created' : 'updated' })
                }
                value={draft.dateField}
              >
                <option value="updated">updated</option>
                <option value="created">created</option>
              </select>
              <label className="filter-panel__field">
                <span>after</span>
                <input
                  onChange={(event) => patch({ after: event.target.value })}
                  type="date"
                  value={draft.after}
                />
              </label>
              <label className="filter-panel__field">
                <span>before</span>
                <input
                  onChange={(event) => patch({ before: event.target.value })}
                  type="date"
                  value={draft.before}
                />
              </label>
            </div>
          </fieldset>

          <fieldset className="filter-panel__group">
            <legend className="filter-panel__legend">Contains</legend>
            <select
              aria-label="Has attachment"
              className="filter-panel__select"
              onChange={(event) =>
                patch({ has: event.target.value === '' ? null : (event.target.value as HasTarget) })
              }
              value={draft.has ?? ''}
            >
              <option value="">anything</option>
              {HAS_TARGETS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </fieldset>

          {!hideFlags && (
            <fieldset className="filter-panel__group">
              <legend className="filter-panel__legend">State</legend>
              <div className="filter-panel__row">
                <TriStateField
                  label="Pinned"
                  onChange={(pinned) => patch({ pinned })}
                  value={draft.pinned}
                />
                <TriStateField
                  label="Archived"
                  onChange={(archived) => patch({ archived })}
                  value={draft.archived}
                />
                <TriStateField
                  label="Trashed"
                  onChange={(trashed) => patch({ trashed })}
                  value={draft.trashed}
                />
              </div>
            </fieldset>
          )}
        </div>
      )}
    </div>
  );
}

interface TriStateFieldProps {
  readonly label: string;
  readonly value: TriState;
  readonly onChange: (value: TriState) => void;
}

function TriStateField({ label, value, onChange }: TriStateFieldProps): React.JSX.Element {
  return (
    <label className="filter-panel__field">
      <span>{label}</span>
      <select onChange={(event) => onChange(event.target.value as TriState)} value={value}>
        <option value="any">either</option>
        <option value="yes">yes</option>
        <option value="no">no</option>
      </select>
    </label>
  );
}
