import type { Note, NoteId } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { filterNotes } from '../filters/evaluate';
import { displayTitle, kindIcon } from './kinds';
import { Modal } from './modal';

/**
 * Quick open and the command list, in one box.
 *
 * One surface rather than two, because the question a person actually has is "get me to the
 * thing" and they should not have to know in advance whether the thing is a note or an action.
 * Typing filters both; `>` restricts to commands, the way every editor does it.
 */

export interface Command {
  readonly id: string;
  readonly label: string;
  readonly hint?: string;
  readonly shortcut?: string;
  readonly run: () => void;
}

export interface CommandPaletteProps {
  readonly open: boolean;
  readonly onClose: () => void;
  readonly commands: readonly Command[];
  readonly notes: readonly Note[];
  readonly onOpenNote: (noteId: NoteId) => void;
}

interface Row {
  readonly key: string;
  readonly icon: string;
  readonly label: string;
  readonly hint: string | undefined;
  readonly shortcut: string | undefined;
  readonly run: () => void;
}

export function CommandPalette({
  open,
  onClose,
  commands,
  notes,
  onOpenNote,
}: CommandPaletteProps): React.JSX.Element | null {
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);

  const rows = useMemo<Row[]>(() => {
    const commandsOnly = query.startsWith('>');
    const needle = (commandsOnly ? query.slice(1) : query).trim().toLowerCase();

    const commandRows: Row[] = commands
      .filter((command) => needle === '' || command.label.toLowerCase().includes(needle))
      .map((command) => ({
        key: `command:${command.id}`,
        icon: '⌘',
        label: command.label,
        hint: command.hint,
        shortcut: command.shortcut,
        run: command.run,
      }));

    if (commandsOnly) {
      return commandRows;
    }

    const noteRows: Row[] = filterNotes(notes, {
      filter: needle === '' ? null : { type: 'text', query: needle, field: 'all' },
      limit: 12,
    }).map((note) => ({
      key: `note:${note.id}`,
      icon: kindIcon(note.kind),
      label: displayTitle(note.title),
      hint: note.excerpt.trim() === '' ? undefined : note.excerpt.slice(0, 90),
      shortcut: undefined,
      run: () => onOpenNote(note.id),
    }));

    // Commands first when the box is empty (that is the "what can I do" case), notes first once
    // something has been typed (that is the "take me there" case).
    return needle === '' ? [...commandRows, ...noteRows] : [...noteRows, ...commandRows];
  }, [commands, notes, onOpenNote, query]);

  if (!open) {
    return null;
  }

  const clamped = Math.min(active, Math.max(rows.length - 1, 0));

  function choose(row: Row | undefined): void {
    if (row === undefined) return;
    onClose();
    row.run();
  }

  return (
    <Modal onClose={onClose} title="Go to, or do" variant="palette">
      <div className="palette">
        <input
          aria-label="Search notes and commands"
          className="palette__input"
          onChange={(event) => {
            setQuery(event.target.value);
            setActive(0);
          }}
          onKeyDown={(event) => {
            if (event.key === 'ArrowDown') {
              event.preventDefault();
              setActive((value) => Math.min(value + 1, rows.length - 1));
            }
            if (event.key === 'ArrowUp') {
              event.preventDefault();
              setActive((value) => Math.max(value - 1, 0));
            }
            if (event.key === 'Enter') {
              event.preventDefault();
              choose(rows[clamped]);
            }
          }}
          placeholder="Type to find a note, or > for commands…"
          type="text"
          value={query}
        />

        {rows.length === 0 ? (
          <p className="palette__empty">Nothing matches “{query}”.</p>
        ) : (
          <ul className="palette__rows">
            {rows.map((row, index) => (
              <li key={row.key}>
                <button
                  className="palette__row"
                  data-active={index === clamped}
                  onClick={() => choose(row)}
                  onMouseEnter={() => setActive(index)}
                  type="button"
                >
                  <span aria-hidden="true" className="palette__icon">
                    {row.icon}
                  </span>
                  <span className="palette__label">{row.label}</span>
                  {row.hint !== undefined && <span className="palette__hint">{row.hint}</span>}
                  {row.shortcut !== undefined && (
                    <kbd className="palette__shortcut">{row.shortcut}</kbd>
                  )}
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </Modal>
  );
}
