import type { Filter, Note, NoteId, RandomMode, ShuffleBagState } from '@rosie-notes/schema';
import { useCallback, useEffect, useRef, useState } from 'react';
import { describeDraft, type FilterDraft } from '../filters/filter-draft';
import { useWorkspace } from '../session/session-context';
import { displayTitle, kindIcon, kindLabel } from './kinds';
import { Modal } from './modal';

/**
 * "Give me one."
 *
 * This is a headline feature, not a debug button. The use case is a tagged library — stories,
 * prompts, ideas you meant to come back to — that is too big to choose from, and the whole point
 * is that the app chooses. So it gets a real surface: the three modes explained in the words that
 * describe what they *do*, the filter it is drawing from shown on the card so a draw is never a
 * mystery, and the shuffle bag's progress visible while you work through it.
 *
 * The three modes come straight from the schema and the server implements all three:
 *
 * - **Surprise me** (`pure`) — uniform, may repeat immediately.
 * - **Least seen first** (`least_seen`) — the default, and the one that makes a library converge
 *   instead of circling the same handful of notes.
 * - **Shuffle bag** (`shuffle_bag`) — no repeats until you have seen everything that matches.
 */

const MODES: readonly { value: RandomMode; label: string; blurb: string }[] = [
  {
    value: 'least_seen',
    label: 'Least seen first',
    blurb: 'Works through the whole set, oldest and least-read first.',
  },
  {
    value: 'shuffle_bag',
    label: 'Shuffle bag',
    blurb: 'No repeats until everything matching has come up once.',
  },
  { value: 'pure', label: 'Surprise me', blurb: 'Uniformly random. May repeat straight away.' },
];

export interface RandomDialogProps {
  readonly open: boolean;
  readonly onClose: () => void;
  /** The filter currently in force. A draw honours it, which is the whole point. */
  readonly filter: Filter | null;
  readonly draft: FilterDraft;
  /** Where the draw came from, for the "drawing from" line. */
  readonly scopeLabel: string;
  readonly onOpenNote: (noteId: NoteId) => void;
}

export function RandomDialog({
  open,
  onClose,
  filter,
  draft,
  scopeLabel,
  onOpenNote,
}: RandomDialogProps): React.JSX.Element | null {
  const workspace = useWorkspace();
  const [mode, setMode] = useState<RandomMode>('least_seen');
  const [drawn, setDrawn] = useState<readonly Note[]>([]);
  const [matchCount, setMatchCount] = useState<number | null>(null);
  const [state, setState] = useState<'idle' | 'drawing' | 'empty' | 'failed'>('idle');

  /**
   * The bag is stored *with the filter it was filled from*, and only counts as current when the
   * two still agree. Changing the filter therefore starts a new bag with no effect and nothing to
   * reset — which is the promise `shuffle_bag` makes, expressed as data rather than as a cleanup
   * somebody could forget to write.
   */
  const filterKey = JSON.stringify(filter);
  const [heldBag, setHeldBag] = useState<{ key: string; state: ShuffleBagState } | null>(null);
  const bag = heldBag !== null && heldBag.key === filterKey ? heldBag.state : null;

  const draw = useCallback(
    async (bagId: ShuffleBagState['id'] | null) => {
      setState('drawing');
      try {
        const response = await workspace.client.search.random({
          mode,
          count: 1,
          markSeen: true,
          ...(filter === null ? {} : { filter }),
          ...(mode === 'shuffle_bag' && bagId !== null ? { bagId } : {}),
        });
        setMatchCount(response.matchCount);
        setHeldBag(response.bag === null ? null : { key: filterKey, state: response.bag });
        if (response.notes.length === 0) {
          setDrawn([]);
          setState('empty');
          return;
        }
        setDrawn(response.notes);
        setState('idle');
        for (const note of response.notes) {
          void workspace.adapter.cache.writeNote(note);
        }
      } catch (error) {
        // `random.no_matches` is a 404 and means the filter is too narrow, not a breakage.
        const code = (error as { code?: string }).code;
        setState(code === 'random.no_matches' ? 'empty' : 'failed');
        setDrawn([]);
      }
    },
    [filter, filterKey, mode, workspace],
  );

  // Opening the dialog should already have drawn something: an empty card with a button on it is
  // one more click between the user and the thing they asked for. The ref keeps the effect
  // dependent on *opening* rather than on the identity of `draw`, which changes with the mode.
  const latestDraw = useRef(draw);
  latestDraw.current = draw;
  const latestBagId = useRef<ShuffleBagState['id'] | null>(null);
  latestBagId.current = bag?.id ?? null;

  useEffect(() => {
    if (open) {
      void latestDraw.current(latestBagId.current);
    }
  }, [open]);

  if (!open) {
    return null;
  }

  const conditions = describeDraft(draft);

  return (
    <Modal onClose={onClose} title="Pick one for me">
      <div className="random">
        <p className="random__scope">
          Drawing from <strong>{scopeLabel}</strong>
          {conditions.length > 0 && <> · {conditions.join(' · ')}</>}
          {matchCount !== null && (
            <>
              {' '}
              — {matchCount} note{matchCount === 1 ? '' : 's'} match
            </>
          )}
        </p>

        <fieldset className="random__modes">
          <legend className="visually-hidden">How to pick</legend>
          {MODES.map((option) => (
            <label className="random__mode" key={option.value}>
              <input
                checked={mode === option.value}
                name="random-mode"
                onChange={() => setMode(option.value)}
                type="radio"
                value={option.value}
              />
              <span>
                <strong>{option.label}</strong>
                <span className="random__blurb">{option.blurb}</span>
              </span>
            </label>
          ))}
        </fieldset>

        {mode === 'shuffle_bag' && bag !== null && (
          <p className="random__bag">
            <progress max={bag.total} value={bag.total - bag.remaining} />
            {bag.remaining} of {bag.total} still to come
            {bag.exhausted && ' — that was the last one, the next draw refills the bag.'}
          </p>
        )}

        <div className="random__result" aria-live="polite">
          {state === 'drawing' && <p className="random__message">Picking…</p>}
          {state === 'failed' && (
            <p className="random__message" role="alert">
              Picking needs the server, and it is not reachable right now.
            </p>
          )}
          {state === 'empty' && (
            <p className="random__message">Nothing matches that filter. Widen it and try again.</p>
          )}
          {state === 'idle' &&
            drawn.map((note) => (
              <button
                className="random__card"
                key={note.id}
                onClick={() => {
                  onOpenNote(note.id);
                  onClose();
                }}
                type="button"
              >
                <span className="random__card-kind">
                  {kindIcon(note.kind)} {kindLabel(note.kind)}
                </span>
                <span className="random__card-title">{displayTitle(note.title)}</span>
                <span className="random__card-excerpt">{note.excerpt}</span>
                <span className="random__card-open">Open it →</span>
              </button>
            ))}
        </div>

        <div className="random__actions">
          <button
            className="button button--primary"
            disabled={state === 'drawing'}
            onClick={() => void draw(bag?.id ?? null)}
            type="button"
          >
            {drawn.length === 0 ? 'Pick one' : 'Another'}
          </button>
          <button className="button button--quiet" onClick={onClose} type="button">
            Close
          </button>
        </div>
      </div>
    </Modal>
  );
}
