import { applyThemeVars, type ThemeMode, toThemePayload } from '@rosie-notes/tokens';
import { useCallback, useEffect, useState } from 'react';

/**
 * Light or dark, from `general/tokens`.
 *
 * The tokens package is the single source: this hook only decides *which* theme and paints its
 * variables onto `<html>`. The editor receives the same payload over the bridge, which is how a
 * WebView and a VSCode webview end up looking like the app that hosts them without either side
 * having a copy of the palette.
 *
 * Three settings, not two. `system` is the default and it *keeps following* the OS — somebody
 * whose machine switches at sunset expects the app to switch with it, and a one-shot read at
 * start-up does not do that. Choosing light or dark pins it, and the pin survives a reload.
 */

const THEME_KEY = 'rosie-notes:theme';

export type ThemePreference = 'system' | ThemeMode;

function storedPreference(): ThemePreference {
  try {
    const stored = globalThis.localStorage?.getItem(THEME_KEY);
    return stored === 'light' || stored === 'dark' ? stored : 'system';
  } catch {
    return 'system';
  }
}

function systemTheme(): ThemeMode {
  return globalThis.matchMedia?.('(prefers-color-scheme: light)').matches === true
    ? 'light'
    : 'dark';
}

export interface ThemeControl {
  /** What is actually on screen. */
  readonly theme: ThemeMode;
  /** What the user asked for, which may be `system`. */
  readonly preference: ThemePreference;
  setPreference(preference: ThemePreference): void;
}

export function useTheme(): ThemeControl {
  const [preference, setPreferenceState] = useState<ThemePreference>(storedPreference);
  const [system, setSystem] = useState<ThemeMode>(systemTheme);

  // Follow the OS for as long as the preference is `system`. The listener is cheap and always
  // attached, so switching back to `system` needs no re-subscription.
  useEffect(() => {
    const query = globalThis.matchMedia?.('(prefers-color-scheme: light)');
    if (query === undefined || typeof query.addEventListener !== 'function') {
      return;
    }
    const onChange = (): void => setSystem(query.matches ? 'light' : 'dark');
    query.addEventListener('change', onChange);
    return () => query.removeEventListener('change', onChange);
  }, []);

  const theme: ThemeMode = preference === 'system' ? system : preference;

  useEffect(() => {
    const root = globalThis.document?.documentElement;
    if (root === undefined) {
      return;
    }
    applyThemeVars(root, toThemePayload(theme));
    root.dataset['theme'] = theme;
    root.style.colorScheme = theme;
  }, [theme]);

  const setPreference = useCallback((next: ThemePreference) => {
    setPreferenceState(next);
    try {
      if (next === 'system') {
        globalThis.localStorage?.removeItem(THEME_KEY);
      } else {
        globalThis.localStorage?.setItem(THEME_KEY, next);
      }
    } catch {
      // Private browsing. The theme simply will not stick, which is not worth telling anyone.
    }
  }, []);

  return { theme, preference, setPreference };
}
