import { isApiError } from '@rosie-notes/client';
import type { Note, NoteId, NoteKind, TagName } from '@rosie-notes/schema';
import type { ThemeMode } from '@rosie-notes/tokens';
import { useCallback, useEffect, useState } from 'react';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNote } from '../hooks/use-store';
import { useWorkspace } from '../session/session-context';
import { BacklinksPanel } from './backlinks-panel';
import { kindHint, kindIcon, kindLabel, NOTE_KINDS, shortWhen } from './kinds';
import { NoteEditor, type SaveState } from './note-editor';
import { EmptyState } from './states';
import { TagInput } from './tag-input';

/**
 * One open note: its metadata, its body, and what links to it.
 *
 * The title, kind and tags live *outside* the CRDT deliberately. They are short, single-valued
 * fields that the list, the search index, the tag counts and the wiki-link picker all read; a
 * last-writer-wins column is both adequate for them and far simpler than a shared type nobody
 * will ever concurrently edit character by character. The body — the thing two people might
 * genuinely type into at once — is the part that is a `Y.Doc`.
 */

const SAVE_LABELS: Record<SaveState, { text: string; hint: string }> = {
  idle: { text: 'Saved', hint: 'Nothing has changed since the last save.' },
  dirty: { text: 'Unsaved…', hint: 'Your changes are on this device; saving shortly.' },
  saving: { text: 'Saving…', hint: 'Sending this note to the server.' },
  saved: { text: 'Saved', hint: 'The server has this version.' },
  offline: {
    text: 'Saved on this device',
    hint: 'The server is not reachable. Your writing is queued and will send on reconnect.',
  },
  error: { text: 'Not saved', hint: 'The server refused the last save. Try again shortly.' },
};

export interface NotePaneProps {
  readonly noteId: NoteId;
  readonly theme: ThemeMode;
  readonly onOpenNote: (noteId: NoteId) => void;
  readonly onCreateLinkedNote: (title: string, parentId: NoteId) => void;
}

export function NotePane({
  noteId,
  theme,
  onOpenNote,
  onCreateLinkedNote,
}: NotePaneProps): React.JSX.Element {
  const workspace = useWorkspace();
  const { note } = useNote(noteId);
  const actions = useNoteActions();
  const [saveState, setSaveState] = useState<SaveState>('idle');
  const [showDetails, setShowDetails] = useState(false);
  const [missing, setMissing] = useState(false);

  // The note may not be in the store yet — a deep link opened cold, or a note created on another
  // device. Fetch it. Only the server *saying* it does not exist counts as missing: a failure to
  // ask is being offline, and telling somebody their note is gone because the wi-fi dropped is
  // the worst possible lie for a notes app to tell.
  useEffect(() => {
    let cancelled = false;
    setMissing(false);
    void (async () => {
      try {
        await workspace.store.loadNote(noteId);
      } catch (error) {
        if (!cancelled && isApiError(error) && error.is('note.not_found')) {
          setMissing(true);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [noteId, workspace]);

  const createLinked = useCallback(
    (title: string) => onCreateLinkedNote(title, noteId),
    [noteId, onCreateLinkedNote],
  );

  if (note === null && missing) {
    return (
      <EmptyState
        icon="🔍"
        title="That note is not here"
        body="It may have been deleted, or it belongs to another account."
      />
    );
  }

  const label = SAVE_LABELS[saveState];

  return (
    <article className="note-pane">
      <header className="note-pane__header">
        <div className="note-pane__title-row">
          <TitleField
            key={noteId}
            note={note}
            onCommit={(title) => void actions.rename(noteId, title)}
          />
          <span className="save-state" data-state={saveState} title={label.hint}>
            <span aria-hidden="true" className="save-state__dot" />
            {label.text}
          </span>
        </div>

        <div className="note-pane__toolbar">
          <label className="note-pane__kind">
            <span className="visually-hidden">Note kind</span>
            <select
              disabled={note === null}
              onChange={(event) => void actions.setKind(noteId, event.target.value as NoteKind)}
              title={note === null ? undefined : kindHint(note.kind)}
              value={note?.kind ?? 'page'}
            >
              {NOTE_KINDS.map((kind) => (
                <option key={kind} value={kind}>
                  {kindIcon(kind)} {kindLabel(kind)}
                </option>
              ))}
            </select>
          </label>

          <button
            aria-pressed={note?.pinned ?? false}
            className="button button--quiet"
            disabled={note === null}
            onClick={() => note !== null && void actions.togglePinned(note)}
            type="button"
          >
            {note?.pinned === true ? '📌 Pinned' : 'Pin'}
          </button>

          <button
            aria-pressed={note?.archived ?? false}
            className="button button--quiet"
            disabled={note === null}
            onClick={() => note !== null && void actions.toggleArchived(note)}
            type="button"
          >
            {note?.archived === true ? 'Archived' : 'Archive'}
          </button>

          {note?.trashed === true ? (
            <button
              className="button button--quiet"
              onClick={() => void actions.restore(noteId)}
              type="button"
            >
              Restore
            </button>
          ) : (
            <button
              className="button button--quiet button--danger"
              onClick={() => void actions.trash(noteId)}
              type="button"
            >
              Trash
            </button>
          )}

          <button
            aria-expanded={showDetails}
            className="button button--quiet"
            onClick={() => setShowDetails(!showDetails)}
            type="button"
          >
            Details
          </button>
        </div>

        <TagInput
          disabled={note === null}
          onChange={(tags) => void actions.setTags(noteId, tags as TagName[])}
          tags={note?.tags ?? []}
        />

        {showDetails && note !== null && (
          <dl className="note-pane__details">
            <div>
              <dt>Words</dt>
              <dd>{note.wordCount}</dd>
            </div>
            <div>
              <dt>Created</dt>
              <dd>{shortWhen(note.createdAt)}</dd>
            </div>
            <div>
              <dt>Updated</dt>
              <dd>{shortWhen(note.updatedAt)}</dd>
            </div>
            <div>
              <dt>Seen</dt>
              <dd>{note.seenCount}×</dd>
            </div>
            <div>
              <dt>Links out</dt>
              <dd>{note.links.length}</dd>
            </div>
            <div>
              <dt>Links in</dt>
              <dd>{note.backlinkCount}</dd>
            </div>
          </dl>
        )}

        {note?.trashed === true && (
          <p className="note-pane__banner" role="status">
            This note is in the trash. Restore it to keep editing.
          </p>
        )}
      </header>

      <div className="note-pane__body">
        <NoteEditor
          noteId={noteId}
          onCreateNote={createLinked}
          onOpenNote={onOpenNote}
          onSaveStateChange={setSaveState}
          readOnly={note?.trashed === true}
          theme={theme}
        />
        <BacklinksPanel
          note={note}
          noteId={noteId}
          onCreateNote={createLinked}
          onOpenNote={onOpenNote}
        />
      </div>
    </article>
  );
}

interface TitleFieldProps {
  readonly note: Note | null;
  readonly onCommit: (title: string) => void;
}

/** The title, edited in place. Committed on blur and on Enter; Escape puts the old one back. */
function TitleField({ note, onCommit }: TitleFieldProps): React.JSX.Element {
  const [draft, setDraft] = useState<string | null>(null);
  const title = draft ?? note?.title ?? '';

  function commit(): void {
    if (draft === null || draft === note?.title) {
      setDraft(null);
      return;
    }
    onCommit(draft);
    setDraft(null);
  }

  return (
    <input
      aria-label="Note title"
      className="note-pane__title"
      onBlur={commit}
      onChange={(event) => setDraft(event.target.value)}
      onKeyDown={(event) => {
        if (event.key === 'Enter') event.currentTarget.blur();
        if (event.key === 'Escape') {
          setDraft(null);
          event.currentTarget.blur();
        }
      }}
      placeholder="Untitled"
      value={title}
    />
  );
}
