import type { Note, NoteId } from '@rosie-notes/schema';
import { filterNotes } from '../filters/evaluate';
import { buildFilter, type FilterDraft } from '../filters/filter-draft';
import { FilterBar } from './filter-bar';
import { ResultList } from './result-list';
import { EmptyState, StaleBanner } from './states';

/**
 * The library pane: everything, narrowed by the filter bar.
 *
 * It filters the *store's* notes locally rather than issuing a request per keystroke. Those notes
 * are already in memory, the same `Filter` AST evaluates over them, and a filter that responds on
 * the keystroke is the difference between a filter people use and one they do not. Search — which
 * needs the server, because it reads bodies — is a separate view with a separate route.
 */

export interface LibraryViewProps {
  readonly notes: readonly Note[];
  readonly draft: FilterDraft;
  readonly onDraftChange: (draft: FilterDraft) => void;
  readonly onOpenNote: (noteId: NoteId) => void;
  readonly onCreateNote: () => void;
  readonly onOpenRandom: () => void;
  readonly loading: boolean;
  readonly stale: boolean;
  readonly reachable: boolean;
}

export function LibraryView({
  notes,
  draft,
  onDraftChange,
  onOpenNote,
  onCreateNote,
  onOpenRandom,
  loading,
  stale,
  reachable,
}: LibraryViewProps): React.JSX.Element {
  // Not memoised: this is a predicate over at most a couple of hundred notes already in memory,
  // and a cache keyed on a freshly-built AST would cost more to compare than the work it saves.
  const shown = filterNotes(notes, { filter: buildFilter(draft), limit: 200 });

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">Library</h1>
        <span className="pane__subtitle">
          {shown.length === notes.length
            ? `${notes.length} note${notes.length === 1 ? '' : 's'}`
            : `${shown.length} of ${notes.length}`}
        </span>
      </header>

      <FilterBar draft={draft} onChange={onDraftChange} />

      {stale && <StaleBanner reachable={reachable} />}

      {shown.length === 0 ? (
        notes.length === 0 ? (
          <EmptyState
            icon={loading ? '⏳' : '📝'}
            title={loading ? 'Opening your library…' : 'Nothing written yet'}
            body={
              loading
                ? undefined
                : 'A note can be a page, a project, an idea, a prompt, a story — whatever you need it to be.'
            }
            action={
              loading ? undefined : (
                <button className="button button--primary" onClick={onCreateNote} type="button">
                  Write the first one
                </button>
              )
            }
          />
        ) : (
          <EmptyState
            icon="🔍"
            title="Nothing matches that filter"
            body="Loosen a condition, or clear the filter to see everything again."
          />
        )
      ) : (
        <>
          <div className="pane__actions">
            <button className="button" onClick={onOpenRandom} type="button">
              🎲 Pick one of these for me
            </button>
          </div>
          <ResultList notes={shown} onOpenNote={onOpenNote} />
        </>
      )}
    </section>
  );
}
