import type { NoteListState, NoteState, SyncStatus } from '@rosie-notes/core';
import type { NoteId } from '@rosie-notes/schema';
import { useCallback, useEffect, useMemo, useSyncExternalStore } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * `NotesStore` is a plain subscribe/emit object with no React in it, which is exactly what
 * `useSyncExternalStore` wants. These hooks are the whole adapter between the two — about thirty
 * lines, and the reason `core` can stay framework-free while Android and VSCode wrap the same
 * store in their own idioms.
 *
 * Every one of these caches its snapshot. `useSyncExternalStore` compares with `Object.is` and
 * `listState()` builds a fresh object each call, so returning it straight from `getSnapshot`
 * would re-render on every check, forever.
 */

export function useNoteList(): NoteListState {
  const { store } = useWorkspace();

  const [subscribe, getSnapshot] = useMemo(() => {
    let snapshot = store.listState();
    return [
      (onChange: () => void) =>
        store.subscribeNotes((state) => {
          snapshot = state;
          onChange();
        }),
      () => snapshot,
    ] as const;
  }, [store]);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function useNote(id: NoteId | null): NoteState {
  const { store } = useWorkspace();

  const [subscribe, getSnapshot] = useMemo(() => {
    if (id === null) {
      const empty: NoteState = { note: null, loading: false, error: null };
      return [() => () => undefined, () => empty] as const;
    }
    let snapshot = store.noteState(id);
    return [
      (onChange: () => void) =>
        store.subscribeNote(id, (state) => {
          snapshot = state;
          onChange();
        }),
      () => snapshot,
    ] as const;
  }, [store, id]);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/** How many metadata writes are waiting for the server. Feeds the sync badge. */
export function usePendingWrites(): number {
  const { writes } = useWorkspace();

  const [subscribe, getSnapshot] = useMemo(() => {
    let snapshot = writes.size;
    return [
      (onChange: () => void) =>
        writes.subscribe((entries) => {
          snapshot = entries.length;
          onChange();
        }),
      () => snapshot,
    ] as const;
  }, [writes]);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function useSyncStatus(): SyncStatus {
  const { engine } = useWorkspace();

  const [subscribe, getSnapshot] = useMemo(() => {
    let snapshot = engine.status;
    return [
      (onChange: () => void) =>
        engine.onStatusChange((status) => {
          snapshot = status;
          onChange();
        }),
      () => snapshot,
    ] as const;
  }, [engine]);

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/**
 * Draw from the cache, then catch up with the server.
 *
 * The order is the point: a cold start paints the last known library immediately instead of a
 * spinner, and the network request only ever replaces it.
 */
export function useLibrary(): { reload: () => Promise<void> } {
  const { store } = useWorkspace();

  const reload = useCallback(async () => {
    try {
      // The store holds one page; `MAX_PAGE_SIZE` is what the server will give in one. Scoped
      // views (a collection, a tag, the trash) page properly through `useNoteQuery` — this is
      // the sidebar's working set, not a promise to hold everything ever written.
      await store.refresh({ limit: 200 });
    } catch {
      // The store keeps the cached list and records the error in its state; the badge shows it.
    }
  }, [store]);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      await store.hydrate();
      if (!cancelled) await reload();
    })();
    return () => {
      cancelled = true;
    };
  }, [store, reload]);

  return { reload };
}
