import type { Filter, NoteId } from '@rosie-notes/schema';
import { useState } from 'react';
import { useNoteActions } from '../hooks/use-note-actions';
import { useNoteQuery } from '../hooks/use-note-query';
import { ResultList } from './result-list';
import { EmptyState, ErrorState, LoadingState, StaleBanner } from './states';

/**
 * The trash, and the archive.
 *
 * One component because they are the same view over a different `flag` node: notes the server is
 * still holding but keeping out of the way. The difference that matters is what you can do with
 * them — trashed notes can be restored or erased, archived ones are simply put back.
 *
 * Erasing asks twice. `purge` destroys the note *and its Yjs history*, which is the one action in
 * this app that no amount of syncing will undo.
 */

const TRASHED: Filter = { type: 'flag', flag: 'trashed', value: true };
const ARCHIVED: Filter = {
  type: 'and',
  filters: [
    { type: 'flag', flag: 'archived', value: true },
    { type: 'flag', flag: 'trashed', value: false },
  ],
};

export interface TrashViewProps {
  readonly variant: 'trash' | 'archive';
  readonly onOpenNote: (noteId: NoteId) => void;
}

export function TrashView({ variant, onOpenNote }: TrashViewProps): React.JSX.Element {
  const actions = useNoteActions();
  const query = useNoteQuery({ filter: variant === 'trash' ? TRASHED : ARCHIVED, limit: 100 });
  const [confirming, setConfirming] = useState<NoteId | null>(null);

  const title = variant === 'trash' ? 'Trash' : 'Archive';

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">{title}</h1>
        <span className="pane__subtitle">
          {query.notes.length} note{query.notes.length === 1 ? '' : 's'}
        </span>
      </header>

      <p className="pane__lede">
        {variant === 'trash'
          ? 'Trashed notes stay here until you erase them. Descendants follow their parent in and out.'
          : 'Archived notes are out of the library but otherwise untouched.'}
      </p>

      {query.stale && <StaleBanner reachable={query.error === null} />}

      {query.loading && query.notes.length === 0 ? (
        <LoadingState label={`Fetching the ${title.toLowerCase()}…`} />
      ) : query.notes.length === 0 ? (
        query.error !== null ? (
          <ErrorState
            title={`Could not load the ${title.toLowerCase()}`}
            body="Nothing matching is cached on this device either."
            onRetry={query.reload}
          />
        ) : (
          <EmptyState
            icon={variant === 'trash' ? '🗑️' : '📦'}
            title={variant === 'trash' ? 'The trash is empty' : 'Nothing is archived'}
          />
        )
      ) : (
        <ResultList
          notes={query.notes}
          onOpenNote={onOpenNote}
          renderActions={(note) => (
            <>
              <button
                className="button button--quiet"
                onClick={() => {
                  void actions.restore(note.id).then(() => query.reload());
                }}
                type="button"
              >
                Restore
              </button>
              {variant === 'trash' &&
                (confirming === note.id ? (
                  <button
                    className="button button--danger"
                    onClick={() => {
                      setConfirming(null);
                      void actions.purge(note.id).then(() => query.reload());
                    }}
                    type="button"
                  >
                    Really erase
                  </button>
                ) : (
                  <button
                    className="button button--quiet button--danger"
                    onClick={() => setConfirming(note.id)}
                    type="button"
                  >
                    Erase
                  </button>
                ))}
            </>
          )}
        />
      )}
    </section>
  );
}
