import type { NoteId, SearchHit } from '@rosie-notes/schema';
import { useEffect, useState } from 'react';
import { buildFilter, type FilterDraft } from '../filters/filter-draft';
import { useWorkspace } from '../session/session-context';
import { FilterBar } from './filter-bar';
import { displayTitle, kindIcon, shortWhen } from './kinds';
import { EmptyState, ErrorState, LoadingState } from './states';

/**
 * Server-side search.
 *
 * Results are a *view*, not application state, so they live here rather than in the store — the
 * library list must not rearrange itself because somebody typed in the search box.
 *
 * The filter bar and the query box compose: `POST /v1/search` takes both, ANDs them, and the
 * filter half is the same AST a smart collection stores. "Everything tagged rust, mentioning
 * async, written this month" is one request.
 *
 * Highlights arrive as HTML from the server, which is the one place in this app that renders
 * markup it did not build. It is safe for a specific reason: the API escapes the whole snippet
 * and only then substitutes `<mark>`, so the only tags that can survive are the ones the search
 * service put there. That contract is tested on the server side; if it ever changes, this is the
 * call site that breaks.
 */

export interface SearchViewProps {
  readonly query: string;
  readonly onQueryChange: (query: string) => void;
  readonly onOpen: (noteId: NoteId) => void;
  readonly draft: FilterDraft;
  readonly onDraftChange: (draft: FilterDraft) => void;
}

export function SearchView({
  query,
  onQueryChange,
  onOpen,
  draft,
  onDraftChange,
}: SearchViewProps): React.JSX.Element {
  const { store } = useWorkspace();
  const [hits, setHits] = useState<SearchHit[]>([]);
  const [total, setTotal] = useState<number | null>(null);
  const [state, setState] = useState<'idle' | 'searching' | 'failed'>('idle');
  const [tookMs, setTookMs] = useState<number | null>(null);

  const filter = buildFilter(draft);
  const filterKey = JSON.stringify(filter);

  useEffect(() => {
    const trimmed = query.trim();
    const activeFilter = filterKey === 'null' ? null : (JSON.parse(filterKey) as typeof filter);

    if (trimmed === '' && activeFilter === null) {
      setHits([]);
      setTotal(null);
      setState('idle');
      return;
    }

    let cancelled = false;
    setState('searching');

    // Debounced: as-you-type search should feel immediate without one request per keystroke.
    const timer = setTimeout(() => {
      void (async () => {
        try {
          const response = await store.search({
            ...(trimmed === '' ? {} : { query: trimmed }),
            ...(activeFilter === null ? {} : { filter: activeFilter }),
            limit: 30,
            includeTotal: true,
          });
          if (cancelled) return;
          setHits(response.items);
          setTotal(response.total);
          setTookMs(response.tookMs);
          setState('idle');
        } catch {
          if (cancelled) return;
          setState('failed');
        }
      })();
    }, 200);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [query, filterKey, store]);

  const asked = query.trim() !== '' || filter !== null;

  return (
    <section className="search pane">
      <header className="pane__header">
        <h1 className="pane__title">Search</h1>
        {state !== 'failed' && asked && (
          <span className="pane__subtitle">
            {total === null ? `${hits.length} shown` : `${total} match${total === 1 ? '' : 'es'}`}
            {tookMs === null ? '' : ` · ${tookMs} ms`}
          </span>
        )}
      </header>

      <label className="search__field">
        <span className="visually-hidden">Search notes</span>
        <input
          // The search view is only mounted by an explicit user action (the search command or
          // clicking Search), so focusing the field is the expected outcome of that action
          // rather than an unrequested focus steal on page load.
          // biome-ignore lint/a11y/noAutofocus: intentional — view is opened on demand
          autoFocus
          className="search__input"
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder="Search everything…"
          type="search"
          value={query}
        />
      </label>

      <FilterBar draft={draft} onChange={onDraftChange} />

      {state === 'failed' && (
        <ErrorState
          title="Search needs the server"
          body="It is not reachable right now. Your notes are still here — the library and its filters work offline."
        />
      )}

      {state === 'searching' && hits.length === 0 && <LoadingState label="Searching…" />}

      {state !== 'failed' && !asked && (
        <EmptyState
          icon="🔎"
          title="Search your whole library"
          body="Words match titles and bodies. Add filters to narrow by tag, kind or date."
        />
      )}

      <ul className="search__results">
        {hits.map((hit) => (
          <li key={hit.note.id}>
            <button className="search__result" onClick={() => onOpen(hit.note.id)} type="button">
              <span className="search__result-title">
                <span aria-hidden="true">{kindIcon(hit.note.kind)}</span>{' '}
                {displayTitle(hit.note.title)}
              </span>
              {hit.highlights.map((highlight) => (
                <span
                  className="search__snippet"
                  // Verified safe, not assumed: api/src/services/search.ts asks FTS5 to mark
                  // matches with control-character sentinels, HTML-escapes the whole snippet,
                  // and only then swaps the sentinels for <mark>. The only unescaped markup
                  // that can reach here is our own <mark>/</mark>.
                  // biome-ignore lint/security/noDangerouslySetInnerHtml: server-escaped, marks only
                  dangerouslySetInnerHTML={{ __html: highlight.snippet }}
                  key={`${highlight.field}:${highlight.snippet}`}
                />
              ))}
              <span className="search__result-meta">
                {hit.note.tags.map((tag) => (
                  <span className="result__tag" key={tag}>
                    #{tag}
                  </span>
                ))}
                <time dateTime={hit.note.updatedAt}>{shortWhen(hit.note.updatedAt)}</time>
              </span>
            </button>
          </li>
        ))}
      </ul>

      {state === 'idle' && asked && hits.length === 0 && (
        <EmptyState icon="🫙" title="Nothing matched" body="Try fewer words, or clear a filter." />
      )}
    </section>
  );
}
