import type { Note, NoteId } from '@rosie-notes/schema';
import type { ReactNode } from 'react';
import { routeToHash } from '../routing/routes';
import { displayTitle, kindIcon, shortWhen } from './kinds';

/**
 * A flat list of notes with enough metadata to choose between them.
 *
 * Every scoped view — a collection, a tag, the trash, the archive — renders this. Search does
 * not, because a search result carries highlighted snippets that are the whole reason to look at
 * it, and flattening those into an excerpt would throw the answer away.
 */

export interface ResultListProps {
  readonly notes: readonly Note[];
  readonly onOpenNote: (noteId: NoteId) => void;
  /** Per-row controls — "restore", "delete forever" — rendered after the metadata. */
  readonly renderActions?: (note: Note) => ReactNode;
}

export function ResultList({
  notes,
  onOpenNote,
  renderActions,
}: ResultListProps): React.JSX.Element {
  return (
    <ul className="result-list">
      {notes.map((note) => (
        <li className="result-list__row" key={note.id}>
          <a
            className="result"
            href={routeToHash({ name: 'note', noteId: note.id })}
            onClick={(event) => {
              if (event.metaKey || event.ctrlKey || event.shiftKey) return;
              event.preventDefault();
              onOpenNote(note.id);
            }}
          >
            <span className="result__title">
              <span aria-hidden="true">{kindIcon(note.kind)}</span> {displayTitle(note.title)}
              {note.pinned && (
                <span aria-label="Pinned" role="img">
                  📌
                </span>
              )}
            </span>
            <span className="result__excerpt">
              {note.excerpt.trim() === '' ? 'Empty note' : note.excerpt}
            </span>
            <span className="result__meta">
              {note.tags.map((tag) => (
                <span className="result__tag" key={tag}>
                  #{tag}
                </span>
              ))}
              <time dateTime={note.updatedAt}>{shortWhen(note.updatedAt)}</time>
            </span>
          </a>
          {renderActions !== undefined && (
            <div className="result-list__actions">{renderActions(note)}</div>
          )}
        </li>
      ))}
    </ul>
  );
}
