import type {
  Note,
  NoteCreateRequestInput,
  NoteId,
  NoteKind,
  NoteUpdateRequest,
  TagName,
} from '@rosie-notes/schema';
import { newId } from '@rosie-notes/schema';
import { useMemo } from 'react';
import { useWorkspace } from '../session/session-context';

/**
 * Every write the UI can make, in one place, and all of them offline-safe.
 *
 * Nothing in the views calls `store.updateNote` directly. They call these, which route through
 * the workspace's {@link WriteQueue}: applied now when the server is there, queued on disk when
 * it is not, and replayed in order on reconnect. Having exactly one door means "does this work
 * offline?" has one answer for the whole app rather than one per button.
 */

/** What a caller may say about a new note. The id is ours to mint, and the title may be empty. */
export type NewNoteInput = Partial<Omit<NoteCreateRequestInput, 'id'>>;

export interface NoteActions {
  /** Mints the id locally, so the note is real — and editable — before the server hears of it. */
  create(input?: NewNoteInput): Promise<NoteId>;
  update(id: NoteId, patch: NoteUpdateRequest): Promise<void>;
  rename(id: NoteId, title: string): Promise<void>;
  setKind(id: NoteId, kind: NoteKind): Promise<void>;
  setTags(id: NoteId, tags: readonly TagName[]): Promise<void>;
  setParent(id: NoteId, parentId: NoteId | null): Promise<void>;
  togglePinned(note: Note): Promise<void>;
  toggleArchived(note: Note): Promise<void>;
  trash(id: NoteId): Promise<void>;
  restore(id: NoteId): Promise<void>;
  purge(id: NoteId): Promise<void>;
}

export function useNoteActions(): NoteActions {
  const workspace = useWorkspace();

  return useMemo<NoteActions>(() => {
    const { writes, adapter } = workspace;

    return {
      async create(input = {}) {
        const noteId = newId<'note'>(adapter.clock());
        await writes.submit({
          kind: 'create',
          noteId,
          input: { kind: 'page', ...input, title: input.title ?? '', id: noteId },
        });
        return noteId;
      },
      async update(id, patch) {
        await writes.submit({ kind: 'update', noteId: id, patch });
      },
      async rename(id, title) {
        await writes.submit({ kind: 'update', noteId: id, patch: { title } });
      },
      async setKind(id, kind) {
        await writes.submit({ kind: 'update', noteId: id, patch: { kind } });
      },
      async setTags(id, tags) {
        await writes.submit({ kind: 'update', noteId: id, patch: { tags: [...tags] } });
      },
      async setParent(id, parentId) {
        await writes.submit({ kind: 'update', noteId: id, patch: { parentId } });
      },
      async togglePinned(note) {
        await writes.submit({ kind: 'update', noteId: note.id, patch: { pinned: !note.pinned } });
      },
      async toggleArchived(note) {
        await writes.submit({
          kind: 'update',
          noteId: note.id,
          patch: { archived: !note.archived },
        });
      },
      async trash(id) {
        await writes.submit({ kind: 'trash', noteId: id });
      },
      async restore(id) {
        await writes.submit({ kind: 'restore', noteId: id });
      },
      async purge(id) {
        await writes.submit({ kind: 'purge', noteId: id });
      },
    };
  }, [workspace]);
}
