import type { Note, NoteId } from '@rosie-notes/schema';
import { useMemo, useState } from 'react';
import { routeToHash } from '../routing/routes';
import { displayTitle, kindIcon, shortWhen } from './kinds';
import { EmptyState } from './states';

/**
 * The library list, flat or as a tree.
 *
 * Notes form a tree — `parentId` is part of the schema, and a project note with its docs and
 * prompts underneath is the shape this app is for — but a tree is a poor way to find something
 * you touched five minutes ago. So both, with a toggle: **Recent** is flat and newest-first,
 * **Tree** nests. The toggle is not a preference dialog; it is two words in the sidebar.
 *
 * It never shows a spinner in place of notes it already has. `stale` is a label on real content,
 * not a reason to hide it.
 */

export type ListMode = 'recent' | 'tree';

export interface NoteListProps {
  readonly notes: readonly Note[];
  readonly selectedId: NoteId | null;
  readonly onSelect: (noteId: NoteId) => void;
  readonly mode: ListMode;
  readonly onModeChange: (mode: ListMode) => void;
  readonly loading: boolean;
  readonly emptyMessage?: string;
}

interface TreeNode {
  readonly note: Note;
  readonly children: TreeNode[];
}

/**
 * Build the forest. A note whose parent is not in the current page is treated as a root rather
 * than being dropped — a partial library must not make notes invisible.
 */
function buildTree(notes: readonly Note[]): TreeNode[] {
  const byId = new Map<NoteId, TreeNode>();
  for (const note of notes) {
    byId.set(note.id, { note, children: [] });
  }

  const roots: TreeNode[] = [];
  for (const node of byId.values()) {
    const parentId = node.note.parentId;
    const parent = parentId === null ? undefined : byId.get(parentId);
    if (parent === undefined || parent === node) {
      roots.push(node);
    } else {
      parent.children.push(node);
    }
  }

  const sortNodes = (nodes: TreeNode[]): void => {
    nodes.sort((left, right) => {
      if (left.note.pinned !== right.note.pinned) {
        return left.note.pinned ? -1 : 1;
      }
      return right.note.updatedAt.localeCompare(left.note.updatedAt);
    });
    for (const node of nodes) {
      sortNodes(node.children);
    }
  };
  sortNodes(roots);
  return roots;
}

export function NoteList({
  notes,
  selectedId,
  onSelect,
  mode,
  onModeChange,
  loading,
  emptyMessage = 'No notes here yet.',
}: NoteListProps): React.JSX.Element {
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set());
  const tree = useMemo(() => (mode === 'tree' ? buildTree(notes) : []), [mode, notes]);

  function toggle(noteId: NoteId): void {
    const next = new Set(collapsed);
    if (next.has(noteId)) {
      next.delete(noteId);
    } else {
      next.add(noteId);
    }
    setCollapsed(next);
  }

  return (
    <div className="note-list">
      <fieldset className="note-list__modes">
        <legend className="visually-hidden">How to order the list</legend>
        {(['recent', 'tree'] as const).map((value) => (
          <button
            aria-pressed={mode === value}
            className="note-list__mode"
            key={value}
            onClick={() => onModeChange(value)}
            type="button"
          >
            {value === 'recent' ? 'Recent' : 'Tree'}
          </button>
        ))}
        <span className="note-list__count">{notes.length}</span>
      </fieldset>

      {notes.length === 0 ? (
        <EmptyState
          icon={loading ? '⏳' : '📭'}
          title={loading ? 'Looking…' : emptyMessage}
          {...(loading ? {} : { body: 'Make one with the New note button, or press Ctrl+K.' })}
        />
      ) : (
        <ul className="note-list__items">
          {mode === 'recent'
            ? notes.map((note) => (
                <li key={note.id}>
                  <NoteRow isSelected={note.id === selectedId} note={note} onSelect={onSelect} />
                </li>
              ))
            : tree.map((node) => (
                <TreeBranch
                  collapsed={collapsed}
                  depth={0}
                  key={node.note.id}
                  node={node}
                  onSelect={onSelect}
                  onToggle={toggle}
                  selectedId={selectedId}
                />
              ))}
        </ul>
      )}
    </div>
  );
}

interface TreeBranchProps {
  readonly node: TreeNode;
  readonly depth: number;
  readonly selectedId: NoteId | null;
  readonly collapsed: ReadonlySet<string>;
  readonly onSelect: (noteId: NoteId) => void;
  readonly onToggle: (noteId: NoteId) => void;
}

function TreeBranch({
  node,
  depth,
  selectedId,
  collapsed,
  onSelect,
  onToggle,
}: TreeBranchProps): React.JSX.Element {
  const hasChildren = node.children.length > 0;
  const isCollapsed = collapsed.has(node.note.id);

  return (
    <li>
      <div className="note-list__branch" style={{ paddingInlineStart: `${depth * 12}px` }}>
        {hasChildren ? (
          <button
            aria-expanded={!isCollapsed}
            aria-label={`${isCollapsed ? 'Expand' : 'Collapse'} ${displayTitle(node.note.title)}`}
            className="note-list__twisty"
            onClick={() => onToggle(node.note.id)}
            type="button"
          >
            {isCollapsed ? '▸' : '▾'}
          </button>
        ) : (
          <span aria-hidden="true" className="note-list__twisty note-list__twisty--leaf" />
        )}
        <NoteRow isSelected={node.note.id === selectedId} note={node.note} onSelect={onSelect} />
      </div>
      {hasChildren && !isCollapsed && (
        <ul className="note-list__items note-list__items--nested">
          {node.children.map((child) => (
            <TreeBranch
              collapsed={collapsed}
              depth={depth + 1}
              key={child.note.id}
              node={child}
              onSelect={onSelect}
              onToggle={onToggle}
              selectedId={selectedId}
            />
          ))}
        </ul>
      )}
    </li>
  );
}

interface NoteRowProps {
  readonly note: Note;
  readonly isSelected: boolean;
  readonly onSelect: (noteId: NoteId) => void;
}

function NoteRow({ note, isSelected, onSelect }: NoteRowProps): React.JSX.Element {
  const excerpt = note.excerpt.trim();

  return (
    <a
      aria-current={isSelected ? 'true' : undefined}
      className="note-list__item"
      data-kind={note.kind}
      data-selected={isSelected}
      href={routeToHash({ name: 'note', noteId: note.id })}
      onClick={(event) => {
        // Let a modifier-click open a new tab the way the href promises.
        if (event.metaKey || event.ctrlKey || event.shiftKey) return;
        event.preventDefault();
        onSelect(note.id);
      }}
    >
      <span className="note-list__title">
        <span aria-hidden="true" className="note-list__icon">
          {kindIcon(note.kind)}
        </span>
        {note.pinned && (
          <span aria-label="Pinned" className="note-list__pin" role="img">
            📌
          </span>
        )}
        {displayTitle(note.title)}
      </span>
      <span className="note-list__excerpt">{excerpt === '' ? 'Empty note' : excerpt}</span>
      <span className="note-list__meta">
        {note.tags.slice(0, 2).map((tag) => (
          <span className="note-list__tag" key={tag}>
            #{tag}
          </span>
        ))}
        <time dateTime={note.updatedAt}>{shortWhen(note.updatedAt)}</time>
      </span>
    </a>
  );
}
