import { isApiError } from '@rosie-notes/client';
import { useState } from 'react';
import type { ThemePreference } from '../hooks/use-theme';
import { normaliseBaseUrl, readOverride, writeOverride } from '../platform/config';
import { useSession } from '../session/session-context';

/**
 * Settings.
 *
 * Three things belong here and each is about being honest with the person using it: which server
 * their notes are going to, how to change their password, and what the encryption claim actually
 * covers. Everything else in this app is a note or a way to find one.
 */

const THEMES: readonly { value: ThemePreference; label: string }[] = [
  { value: 'system', label: 'Match my system' },
  { value: 'light', label: 'Light' },
  { value: 'dark', label: 'Dark' },
];

export interface SettingsViewProps {
  readonly preference: ThemePreference;
  readonly onPreferenceChange: (preference: ThemePreference) => void;
}

export function SettingsView({
  preference,
  onPreferenceChange,
}: SettingsViewProps): React.JSX.Element {
  const { user, baseUrl, signOut } = useSession();
  const [draft, setDraft] = useState(() => readOverride(globalThis.localStorage) ?? '');
  const [saved, setSaved] = useState(false);
  const [invalid, setInvalid] = useState(false);

  function applyServer(): void {
    const trimmed = draft.trim();
    if (trimmed === '') {
      writeOverride(globalThis.localStorage, null);
      setInvalid(false);
      setSaved(true);
      return;
    }
    const normalised = normaliseBaseUrl(trimmed);
    if (normalised === null) {
      setInvalid(true);
      setSaved(false);
      return;
    }
    writeOverride(globalThis.localStorage, normalised);
    setInvalid(false);
    setSaved(true);
  }

  return (
    <section className="settings pane">
      <h1 className="settings__title">Settings</h1>

      <section className="settings__group">
        <h2 className="settings__heading">Account</h2>
        {user === null ? (
          <p className="settings__text">Signed in, but the server has not confirmed who yet.</p>
        ) : (
          <p className="settings__text">
            Signed in as <strong>{user.username}</strong> ({user.email})
            {user.emailVerified ? '' : ' — email not yet verified'}.
          </p>
        )}
        <div className="settings__actions">
          <button className="button" onClick={() => void signOut()} type="button">
            Sign out
          </button>
          <button
            className="button button--danger"
            onClick={() => void signOut({ forget: true })}
            type="button"
          >
            Sign out and forget this device
          </button>
        </div>
        <p className="settings__hint">
          Forgetting clears the local cache. Nothing is deleted from the server, and anything not
          yet synced is lost — so do it while the sync badge says everything is up to date.
        </p>
      </section>

      <ChangePassword />

      <section className="settings__group">
        <h2 className="settings__heading">Appearance</h2>
        <div className="settings__actions">
          {THEMES.map((option) => (
            <button
              aria-pressed={preference === option.value}
              className="button"
              key={option.value}
              onClick={() => onPreferenceChange(option.value)}
              type="button"
            >
              {option.label}
            </button>
          ))}
        </div>
        <p className="settings__hint">
          “Match my system” keeps following your machine, including when it switches at sunset.
        </p>
      </section>

      <section className="settings__group">
        <h2 className="settings__heading">Server</h2>
        <p className="settings__text">
          Currently talking to <code>{baseUrl === '' ? 'this origin' : baseUrl}</code>.
        </p>
        <label className="field">
          <span className="field__label">Point this app at a different server</span>
          <input
            className="field__input"
            onChange={(event) => {
              setDraft(event.target.value);
              setSaved(false);
            }}
            placeholder="https://notes.example.org"
            value={draft}
          />
          <span className="field__hint">
            Leave empty to use the address this build was made with. Takes effect on reload.
          </span>
        </label>
        {invalid && (
          <p className="settings__error" role="alert">
            That is not an http(s) address.
          </p>
        )}
        {saved && <p className="settings__text">Saved. Reload to connect.</p>}
        <div className="settings__actions">
          <button className="button" onClick={applyServer} type="button">
            Save
          </button>
          <button
            className="button button--quiet"
            onClick={() => globalThis.location.reload()}
            type="button"
          >
            Reload
          </button>
        </div>
      </section>

      <section className="settings__group">
        <h2 className="settings__heading">Keyboard</h2>
        <dl className="settings__shortcuts">
          <div>
            <dt>
              <kbd>Ctrl</kbd>/<kbd>⌘</kbd> + <kbd>K</kbd>
            </dt>
            <dd>Go to a note, or run a command</dd>
          </div>
          <div>
            <dt>
              <kbd>Ctrl</kbd> + <kbd>P</kbd>
            </dt>
            <dd>Quick open</dd>
          </div>
          <div>
            <dt>
              <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd>
            </dt>
            <dd>Search everything</dd>
          </div>
          <div>
            <dt>
              <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>N</kbd>
            </dt>
            <dd>New note</dd>
          </div>
          <div>
            <dt>
              <kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>R</kbd>
            </dt>
            <dd>Pick one for me</dd>
          </div>
          <div>
            <dt>
              <kbd>Ctrl</kbd> + <kbd>S</kbd>
            </dt>
            <dd>Save and sync now</dd>
          </div>
          <div>
            <dt>
              <kbd>Escape</kbd>
            </dt>
            <dd>Close whatever is open</dd>
          </div>
        </dl>
      </section>

      <section className="settings__group">
        <h2 className="settings__heading">What “encrypted” means here</h2>
        <p className="settings__text">
          The database and the attachment blobs are encrypted on disk, and the connection is over
          TLS. That protects a stolen disk, a leaked backup, and traffic in transit.
        </p>
        <p className="settings__text">
          It is <strong>not</strong> end-to-end encryption. The server holds the keys — which is
          what makes search, sharing and password reset work — so whoever runs the server can read
          your notes. Nobody will tell you otherwise on this page.
        </p>
      </section>
    </section>
  );
}

/** Change password, in place. The server issues fresh tokens, so this never signs you out here. */
function ChangePassword(): React.JSX.Element {
  const { changePassword } = useSession();
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [signOutOthers, setSignOutOthers] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  async function submit(): Promise<void> {
    setBusy(true);
    setError(null);
    setDone(null);
    try {
      const revoked = await changePassword({
        currentPassword: current,
        newPassword: next,
        signOutOtherSessions: signOutOthers,
      });
      setCurrent('');
      setNext('');
      setDone(
        revoked === 0
          ? 'Password changed.'
          : `Password changed, and ${revoked} other session${revoked === 1 ? '' : 's'} signed out.`,
      );
    } catch (failure) {
      setError(
        isApiError(failure)
          ? failure.code === 'auth.invalid_credentials'
            ? 'That current password is not right.'
            : failure.message
          : 'Changing your password needs the server, and it is not reachable.',
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="settings__group">
      <h2 className="settings__heading">Password</h2>
      <label className="field">
        <span className="field__label">Current password</span>
        <input
          autoComplete="current-password"
          className="field__input"
          onChange={(event) => setCurrent(event.target.value)}
          type="password"
          value={current}
        />
      </label>
      <label className="field">
        <span className="field__label">New password</span>
        <input
          autoComplete="new-password"
          className="field__input"
          minLength={10}
          onChange={(event) => setNext(event.target.value)}
          type="password"
          value={next}
        />
        <span className="field__hint">At least 10 characters.</span>
      </label>
      <label className="settings__checkbox">
        <input
          checked={signOutOthers}
          onChange={(event) => setSignOutOthers(event.target.checked)}
          type="checkbox"
        />
        <span>Sign my other devices out</span>
      </label>
      {error !== null && (
        <p className="settings__error" role="alert">
          {error}
        </p>
      )}
      {done !== null && (
        <p className="settings__text" role="status">
          {done}
        </p>
      )}
      <div className="settings__actions">
        <button
          className="button"
          disabled={busy || current === '' || next.length < 10}
          onClick={() => void submit()}
          type="button"
        >
          {busy ? 'Changing…' : 'Change password'}
        </button>
      </div>
    </section>
  );
}
