import { isApiError } from '@rosie-notes/client';
import type { Collection, CollectionId, CollectionType, Filter, NoteId } from '@rosie-notes/schema';
import { useState } from 'react';
import {
  buildFilter,
  describeDraft,
  EMPTY_FILTER_DRAFT,
  type FilterDraft,
} from '../filters/filter-draft';
import { useCollections, useNoteQuery } from '../hooks/use-note-query';
import { routeToHash } from '../routing/routes';
import { useWorkspace } from '../session/session-context';
import { FilterBar } from './filter-bar';
import { Modal } from './modal';
import { ResultList } from './result-list';
import { EmptyState, ErrorState, LoadingState, StaleBanner } from './states';

/**
 * Collections: manual sets and saved filters.
 *
 * The schema makes the distinction a discriminated union rather than a nullable column, and this
 * UI keeps it that way — a smart collection cannot be created without a filter, because the
 * create form will not let you. The filter it saves is the same `Filter` AST the filter bar
 * builds and the server compiles, so "the notes this collection contains" has exactly one
 * definition on both sides.
 */

const TYPES: readonly { value: CollectionType; label: string; blurb: string }[] = [
  { value: 'project', label: 'Project', blurb: 'Notes, docs and prompts for one codebase.' },
  { value: 'library', label: 'Library', blurb: 'A browsable set with a random pick.' },
  { value: 'reference', label: 'Reference', blurb: 'Long-lived material you look things up in.' },
  { value: 'inbox', label: 'Inbox', blurb: 'Quick capture, expected to be emptied.' },
  { value: 'custom', label: 'Custom', blurb: 'Anything else.' },
];

export interface CollectionsViewProps {
  readonly onOpenCollection: (collectionId: CollectionId) => void;
}

export function CollectionsView({ onOpenCollection }: CollectionsViewProps): React.JSX.Element {
  const { collections, loading, failed, reload } = useCollections();
  const [creating, setCreating] = useState(false);

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">Collections</h1>
        <button className="button button--primary" onClick={() => setCreating(true)} type="button">
          New collection
        </button>
      </header>

      {loading && collections.length === 0 && <LoadingState label="Fetching your collections…" />}

      {failed && collections.length === 0 && !loading && (
        <ErrorState
          title="Collections need the server"
          body="They are defined server-side, so this list is empty until it is reachable."
          onRetry={reload}
        />
      )}

      {!loading && !failed && collections.length === 0 && (
        <EmptyState
          icon="🗂️"
          title="No collections yet"
          body="A collection is either a set you pick by hand or a filter that keeps itself up to date."
          action={
            <button className="button" onClick={() => setCreating(true)} type="button">
              Make the first one
            </button>
          }
        />
      )}

      <ul className="collection-grid">
        {collections.map((collection) => (
          <li key={collection.id}>
            <a
              className="collection-card"
              href={routeToHash({ name: 'collection', collectionId: collection.id })}
              onClick={(event) => {
                if (event.metaKey || event.ctrlKey || event.shiftKey) return;
                event.preventDefault();
                onOpenCollection(collection.id);
              }}
            >
              <span className="collection-card__icon" aria-hidden="true">
                {collection.icon ?? (collection.mode === 'smart' ? '🔎' : '🗂️')}
              </span>
              <span className="collection-card__name">{collection.name}</span>
              <span className="collection-card__meta">
                {collection.mode === 'smart' ? 'Smart' : 'Manual'} · {collection.type} ·{' '}
                {collection.noteCount} note{collection.noteCount === 1 ? '' : 's'}
              </span>
              {collection.description !== null && (
                <span className="collection-card__description">{collection.description}</span>
              )}
            </a>
          </li>
        ))}
      </ul>

      {creating && (
        <CreateCollectionDialog
          onClose={() => setCreating(false)}
          onCreated={(collection) => {
            setCreating(false);
            reload();
            onOpenCollection(collection.id);
          }}
        />
      )}
    </section>
  );
}

interface CreateCollectionDialogProps {
  readonly onClose: () => void;
  readonly onCreated: (collection: Collection) => void;
}

function CreateCollectionDialog({
  onClose,
  onCreated,
}: CreateCollectionDialogProps): React.JSX.Element {
  const workspace = useWorkspace();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [type, setType] = useState<CollectionType>('custom');
  const [mode, setMode] = useState<'manual' | 'smart'>('manual');
  const [draft, setDraft] = useState<FilterDraft>(EMPTY_FILTER_DRAFT);
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);

  const filter = buildFilter(draft);

  async function submit(): Promise<void> {
    if (name.trim() === '') {
      setProblem('Give it a name.');
      return;
    }
    if (mode === 'smart' && filter === null) {
      setProblem('A smart collection needs at least one condition.');
      return;
    }
    setBusy(true);
    setProblem(null);
    try {
      const created = await workspace.client.collections.create(
        mode === 'smart'
          ? {
              mode: 'smart',
              name: name.trim(),
              type,
              filter: filter as Filter,
              ...(description.trim() === '' ? {} : { description: description.trim() }),
            }
          : {
              mode: 'manual',
              name: name.trim(),
              type,
              ...(description.trim() === '' ? {} : { description: description.trim() }),
            },
      );
      onCreated(created);
    } catch (error) {
      setProblem(
        isApiError(error)
          ? error.message
          : 'Collections are created on the server, and it is not reachable.',
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <Modal onClose={onClose} title="New collection">
      <div className="form">
        <label className="field">
          <span className="field__label">Name</span>
          <input
            className="field__input"
            onChange={(event) => setName(event.target.value)}
            value={name}
          />
        </label>

        <label className="field">
          <span className="field__label">Description</span>
          <input
            className="field__input"
            onChange={(event) => setDescription(event.target.value)}
            placeholder="Optional"
            value={description}
          />
        </label>

        <fieldset className="field">
          <legend className="field__label">Membership</legend>
          <div className="form__choices">
            {(['manual', 'smart'] as const).map((value) => (
              <label className="form__choice" key={value}>
                <input
                  checked={mode === value}
                  name="collection-mode"
                  onChange={() => setMode(value)}
                  type="radio"
                />
                <span>
                  <strong>{value === 'manual' ? 'Picked by hand' : 'A saved filter'}</strong>
                  <span className="form__blurb">
                    {value === 'manual'
                      ? 'You add and remove notes yourself.'
                      : 'Whatever matches right now is in it.'}
                  </span>
                </span>
              </label>
            ))}
          </div>
        </fieldset>

        <label className="field">
          <span className="field__label">Type</span>
          <select
            className="field__input"
            onChange={(event) => setType(event.target.value as CollectionType)}
            value={type}
          >
            {TYPES.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label} — {option.blurb}
              </option>
            ))}
          </select>
        </label>

        {mode === 'smart' && (
          <div className="field">
            <span className="field__label">Which notes</span>
            <FilterBar draft={draft} onChange={setDraft} />
            <p className="field__hint">
              {filter === null
                ? 'Add a condition — a smart collection with no filter is every note.'
                : describeDraft(draft).join(' · ')}
            </p>
          </div>
        )}

        {problem !== null && (
          <p className="form__error" role="alert">
            {problem}
          </p>
        )}

        <div className="form__actions">
          <button
            className="button button--primary"
            disabled={busy}
            onClick={() => void submit()}
            type="button"
          >
            {busy ? 'Creating…' : 'Create'}
          </button>
          <button className="button button--quiet" onClick={onClose} type="button">
            Cancel
          </button>
        </div>
      </div>
    </Modal>
  );
}

export interface CollectionViewProps {
  readonly collectionId: CollectionId;
  readonly draft: FilterDraft;
  readonly onDraftChange: (draft: FilterDraft) => void;
  readonly onOpenNote: (noteId: NoteId) => void;
  readonly onBack: () => void;
}

/** One collection: its notes, and — for a smart one — the filter that defines them. */
export function CollectionView({
  collectionId,
  draft,
  onDraftChange,
  onOpenNote,
  onBack,
}: CollectionViewProps): React.JSX.Element {
  const { collections, loading, failed } = useCollections();
  const collection = collections.find((candidate) => candidate.id === collectionId) ?? null;
  const extra = buildFilter(draft);

  const query = useNoteQuery({
    collectionId,
    limit: 100,
    ...(extra === null ? {} : { filter: extra }),
  });

  if (collection === null && loading) {
    return <LoadingState label="Opening the collection…" />;
  }

  if (collection === null) {
    return (
      <ErrorState
        title="That collection is not here"
        body={
          failed
            ? 'Collections are defined server-side and the server is not reachable.'
            : 'It may have been deleted.'
        }
        onRetry={onBack}
      />
    );
  }

  return (
    <section className="pane">
      <header className="pane__header">
        <h1 className="pane__title">
          <span aria-hidden="true">{collection.icon ?? '🗂️'}</span> {collection.name}
        </h1>
        <span className="pane__subtitle">
          {collection.mode === 'smart' ? 'Smart collection' : 'Manual collection'} ·{' '}
          {collection.noteCount} note{collection.noteCount === 1 ? '' : 's'}
        </span>
      </header>

      {collection.description !== null && <p className="pane__lede">{collection.description}</p>}

      <FilterBar draft={draft} onChange={onDraftChange} />

      {query.stale && <StaleBanner reachable={query.error === null} />}

      {query.loading && query.notes.length === 0 ? (
        <LoadingState label="Fetching the notes in this collection…" />
      ) : query.notes.length === 0 ? (
        <EmptyState
          icon="📭"
          title="Nothing in here"
          body={
            collection.mode === 'smart'
              ? 'No note matches this collection’s filter right now.'
              : 'Add notes to it from a note’s own menu.'
          }
        />
      ) : (
        <ResultList notes={query.notes} onOpenNote={onOpenNote} />
      )}

      {query.hasMore && (
        <button className="button" onClick={query.loadMore} type="button">
          Load more
        </button>
      )}
    </section>
  );
}
