import { isApiError } from '@rosie-notes/client';
import { type FormEvent, useState } from 'react';
import type { Route } from '../routing/routes';
import { routeToHash } from '../routing/routes';
import { useSession } from '../session/session-context';

/**
 * Everything that happens before there is a session: sign in, register, and the two halves of a
 * password reset.
 *
 * One component with four faces rather than four routes' worth of duplicated card chrome. The
 * route still decides which face is shown — a reset link in an email has to be a real address —
 * but the fields, the error handling and the "signing in to <server>" line are written once.
 */

type Face = 'signIn' | 'register' | 'forgot' | 'reset';

/** Turn whatever came back into something worth reading. */
function describe(error: unknown): string {
  if (isApiError(error)) {
    switch (error.code) {
      case 'auth.invalid_credentials':
        return 'That username or password is not right.';
      case 'auth.email_taken':
        return 'There is already an account with that email address.';
      case 'auth.username_taken':
        return 'That username is taken.';
      case 'auth.weak_password':
        return 'That password is too weak. Length beats punctuation — try a few words.';
      case 'auth.registration_closed':
        return 'This server is not accepting new accounts.';
      case 'auth.reset_token_invalid':
        return 'That reset link is not valid. Ask for a new one.';
      case 'auth.reset_token_expired':
        return 'That reset link has expired. Ask for a new one.';
      case 'rate_limit.exceeded':
        return error.retryAfterSeconds === null
          ? 'Too many attempts. Try again shortly.'
          : `Too many attempts. Try again in ${error.retryAfterSeconds} seconds.`;
      default:
        return error.message;
    }
  }
  if (error instanceof Error) {
    return `Could not reach the server. ${error.message}`;
  }
  return 'Something went wrong.';
}

export interface AuthViewProps {
  readonly route: Route;
  /** Where to go once there is a session. */
  readonly onSignedIn: () => void;
  readonly onNavigate: (route: Route) => void;
}

export function AuthView({ route, onSignedIn, onNavigate }: AuthViewProps): React.JSX.Element {
  const session = useSession();
  const { baseUrl, startupError } = session;

  const face: Face =
    route.name === 'register'
      ? 'register'
      : route.name === 'forgotPassword'
        ? 'forgot'
        : route.name === 'resetPassword'
          ? 'reset'
          : 'signIn';
  const next = route.name === 'signIn' || route.name === 'register' ? route.next : null;

  const [identifier, setIdentifier] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [token, setToken] = useState(route.name === 'resetPassword' ? route.token : '');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  async function submit(event: FormEvent): Promise<void> {
    event.preventDefault();
    setBusy(true);
    setError(null);
    setDone(null);
    try {
      switch (face) {
        case 'signIn':
          await session.signIn(identifier, password);
          onSignedIn();
          break;
        case 'register':
          await session.register({ username: identifier, email, password });
          onSignedIn();
          break;
        case 'forgot':
          await session.requestPasswordReset(email);
          setDone(
            'If that address has an account, a reset link is on its way. It expires shortly.',
          );
          break;
        default:
          await session.confirmPasswordReset(token, password);
          setDone('Password changed, and every session was signed out. Sign in with the new one.');
          break;
      }
    } catch (failure) {
      setError(describe(failure));
    } finally {
      setBusy(false);
    }
  }

  const signInHash = routeToHash({ name: 'signIn', next });
  const registerHash = routeToHash({ name: 'register', next });

  return (
    <main className="auth">
      {/*
        A distinct form id and name matter more than they look. Browsers scope saved passwords
        by ORIGIN, not by path — so when this app is served from a domain that already has a
        different login, the password manager will offer that other credential here. Naming the
        form separately is what lets Chrome file this as its own entry instead of treating it as
        the same login and overwriting it. Serving Notes from its own subdomain is the complete
        fix; this is the part the page itself can do.
      */}
      <form
        className="auth__card"
        id="rosie-notes-auth"
        name="rosie-notes-auth"
        onSubmit={(event) => void submit(event)}
      >
        <h1 className="auth__title">Notes</h1>
        {/*
          A Notes account is its own thing — it is not the login used by anything else on the
          same domain, and someone arriving here after signing in elsewhere will reasonably
          expect it to be. Saying so once, here, costs a line and prevents the confusion.
          The server is shown underneath because a self-hoster needs to know which one this
          build talks to, but it is secondary and styled as such.
        */}
        <p className="auth__note auth__note--lead">
          {face === 'forgot' || face === 'reset'
            ? 'Reset the password for your Notes account.'
            : 'Notes has its own account, separate from any other sign-in on this site.'}
        </p>
        <p className="auth__server">
          <span className="auth__server-label">Server</span>{' '}
          <code>{baseUrl === '' ? 'this origin' : baseUrl}</code>
        </p>

        {startupError !== null && (
          <p className="auth__error" role="alert">
            The app could not start properly: {startupError.message}
          </p>
        )}

        {next !== null && face !== 'forgot' && face !== 'reset' && (
          <p className="auth__note">Sign in and you will be taken back where you were.</p>
        )}

        {(face === 'signIn' || face === 'register') && (
          <label className="field">
            <span className="field__label">
              {face === 'signIn' ? 'Username or email' : 'Username'}
            </span>
            <input
              autoComplete="username"
              className="field__input"
              name="identifier"
              onChange={(event) => setIdentifier(event.target.value)}
              required
              value={identifier}
            />
          </label>
        )}

        {(face === 'register' || face === 'forgot') && (
          <label className="field">
            <span className="field__label">Email</span>
            <input
              autoComplete="email"
              className="field__input"
              name="email"
              onChange={(event) => setEmail(event.target.value)}
              required
              type="email"
              value={email}
            />
            {face === 'register' && (
              <span className="field__hint">Used for password resets, and nothing else.</span>
            )}
          </label>
        )}

        {face === 'reset' && (
          <label className="field">
            <span className="field__label">Reset code</span>
            <input
              className="field__input"
              name="token"
              onChange={(event) => setToken(event.target.value)}
              required
              value={token}
            />
            <span className="field__hint">From the link in the email.</span>
          </label>
        )}

        {face !== 'forgot' && (
          <label className="field">
            <span className="field__label">{face === 'reset' ? 'New password' : 'Password'}</span>
            <input
              autoComplete={face === 'signIn' ? 'current-password' : 'new-password'}
              className="field__input"
              minLength={face === 'signIn' ? undefined : 10}
              name="password"
              onChange={(event) => setPassword(event.target.value)}
              required
              type="password"
              value={password}
            />
            {face !== 'signIn' && (
              <span className="field__hint">At least 10 characters. Length beats punctuation.</span>
            )}
          </label>
        )}

        {error !== null && (
          <p className="auth__error" role="alert">
            {error}
          </p>
        )}
        {done !== null && (
          <p className="auth__done" role="status">
            {done}
          </p>
        )}

        <button className="button button--primary" disabled={busy} type="submit">
          {busy
            ? 'Working…'
            : face === 'signIn'
              ? 'Sign in'
              : face === 'register'
                ? 'Create account'
                : face === 'forgot'
                  ? 'Send a reset link'
                  : 'Set the new password'}
        </button>

        <nav className="auth__links">
          {face !== 'signIn' && (
            <a
              href={signInHash}
              onClick={(event) => {
                event.preventDefault();
                onNavigate({ name: 'signIn', next });
              }}
            >
              I already have an account
            </a>
          )}
          {face !== 'register' && (
            <a
              href={registerHash}
              onClick={(event) => {
                event.preventDefault();
                onNavigate({ name: 'register', next });
              }}
            >
              I need an account
            </a>
          )}
          {face === 'signIn' && (
            <a
              href={routeToHash({ name: 'forgotPassword' })}
              onClick={(event) => {
                event.preventDefault();
                onNavigate({ name: 'forgotPassword' });
              }}
            >
              I forgot my password
            </a>
          )}
        </nav>

        <p className="auth__footnote">
          Notes are encrypted at rest on the server. That protects a stolen disk or a leaked backup
          — it is not end-to-end encryption, and whoever runs the server can read them.
        </p>
      </form>
    </main>
  );
}
